# Identifiant "d'emetteur" = SN1 (8 chiffres) + SN2 (12 hexa, = adresse MAC) lus sur l'etiquette sous la centrale.
# SN2 est aussi lu dans l'OPEN de la centrale (certain) ; SN1 n'est transmis nulle part [a notre connaissance] :
# il se saisit une fois dans le tableau de bord (clic sur le logo de la centrale) ou avec --source-id.
SOURCE_ID_OVERRIDE = None        # --source-id (20 caracteres), prioritaire sur le reglage du tableau de bord
SOURCE_ID_DEFAULT_SN1 = "00000000"
CENTRALE_MODELS = {"": "Centrale Myfox", "zen": "Centrale Evology Zen", "hc2": "Centrale Home Control 2",
                   "hcpro": "Centrale Home Control Pro", "autre": "Centrale Myfox"}

# Modele de centrale deduit de l'en-tete (OUI = 3 premiers octets) de l'adresse MAC. CERTAIN pour 0004a3 (Zen) et
# d88039 (HC2, releves d'un testeur). MAC inconnue ou absente => "autre" (touches tactiles masquees : seule la Zen
# les porte, a notre connaissance). Ajouter ici l'OUI d'un autre modele des qu'un releve le confirme.
OUI_MODELS = {"0004a3": "zen", "d88039": "hc2"}
TOUCH_BUTTON_MODELS = ("zen",)


def centrale_model(mac):
    """(modele, reconnu) d'apres la MAC ; inconnue => ("autre", False)."""
    oui = re.sub(r"[^0-9a-f]", "", str(mac or "").lower())[:6]
    m = OUI_MODELS.get(oui)
    return (m, True) if m else ("autre", False)


def make_source_id(settings, mac=None):
    """SN1 (reglage) + SN2 (reglage, sinon MAC lue a l'ouverture de session) = 20 caracteres."""
    if SOURCE_ID_OVERRIDE:
        return SOURCE_ID_OVERRIDE
    settings = settings or {}
    sn2 = re.sub(r"[^0-9a-f]", "", str(settings.get("sn2") or mac or settings.get("detected_mac") or "").lower())[:12].rjust(12, "0")
    sn1 = re.sub(r"\D", "", str(settings.get("sn1") or ""))[:8]
    if not sn1:
        # SN1 non saisi : repli sur celui vu dans un ordre du vrai serveur (mode relais), s'il porte le meme SN2
        det = settings.get("detected") or {}
        if det.get("sn1") and det.get("sn2") == sn2:
            sn1 = det["sn1"]
    return (sn1 or SOURCE_ID_DEFAULT_SN1).rjust(8, "0") + sn2


MAC_SEEN_RE = re.compile(r'"mac"\s*:\s*"([0-9a-f]{12})"')
SOURCE_SEEN_RE = re.compile(r'"source"\s*:\s*"(\d{8})([0-9a-f]{12})"')
