# --------------------------------------------------------------------------
# Outils de protocole
# --------------------------------------------------------------------------
# Heure affichee et ecrite dans les journaux : TOUJOURS l'heure de Paris, avec passage automatique a l'heure
# d'ete (dernier dimanche de mars, 01:00 UTC) et a l'heure d'hiver (dernier dimanche d'octobre, 01:00 UTC),
# quel que soit le fuseau reglé sur l'ordinateur (un PC reglé sur « UTC+01:00 » fixe, sans heure d'ete,
# affichait une heure de retard l'ete). Les horodatages du protocole (now, ts, Date: GMT) restent en UTC.
try:
    from zoneinfo import ZoneInfo
    PARIS_TZ = ZoneInfo("Europe/Paris")
    datetime.datetime.fromtimestamp(0, PARIS_TZ)
except Exception:                      # pas de zoneinfo ou pas de base de fuseaux (Windows sans tzdata)
    PARIS_TZ = None
_EPOCH = datetime.datetime(1970, 1, 1)


def _eu_offset_hours(ts):
    """Decalage de Paris en heures (1 ou 2) d'apres la regle europeenne, sans base de fuseaux."""
    year = (_EPOCH + datetime.timedelta(seconds=ts)).year

    def last_sunday(month):
        d = datetime.datetime(year, month, 31, 1, 0, 0)
        while d.weekday() != 6:
            d -= datetime.timedelta(days=1)
        return (d - _EPOCH).total_seconds()
    return 2 if last_sunday(3) <= ts < last_sunday(10) else 1


def local_dt(ts=None):
    """Date et heure de Paris (datetime sans fuseau) pour un horodatage Unix (maintenant par defaut)."""
    ts = time.time() if ts is None else ts
    if PARIS_TZ is not None:
        return datetime.datetime.fromtimestamp(ts, PARIS_TZ).replace(tzinfo=None)
    return _EPOCH + datetime.timedelta(seconds=ts + 3600 * _eu_offset_hours(ts))


def local_ts(dt):
    """Horodatage Unix d'une heure de Paris (inverse de local_dt ; a l'heure ambigue de fin d'ete : la 1re)."""
    base = (dt - _EPOCH).total_seconds()
    for off in (2, 1):
        if local_dt(base - 3600 * off) == dt:
            return base - 3600 * off
    return base - 3600


def http_date():
    d = datetime.datetime.now(datetime.timezone.utc)
    return "%s, %02d %s %04d %02d:%02d:%02d GMT" % (
        JOURS[d.weekday()], d.day, MOIS[d.month - 1], d.year, d.hour, d.minute, d.second)


def make_frame(body):
    """Trame = 4 chiffres (longueur) + corps."""
    raw = body.encode("latin-1", "replace")
    return ("%04d" % len(raw)).encode("ascii") + raw


class Deframer(object):
    """Decoupe un flux TCP en messages (4 chiffres de longueur + corps)."""

    def __init__(self):
        self.buf = b""

    def feed(self, data):
        self.buf += data
        out = []
        while True:
            if len(self.buf) < 4:
                break
            if not self.buf[:4].isdigit():
                self.buf = self.buf[1:]          # octet parasite : on resynchronise
                continue
            n = int(self.buf[:4])
            if len(self.buf) < 4 + n:
                break
            out.append(self.buf[4:4 + n].decode("latin-1"))
            self.buf = self.buf[4 + n:]
        return out


def short(a, n=60):
    return a if len(a) <= n else "%s...(%d car.)" % (a[:n], len(a))


# Ordre 621 (installation d'une camera) : il porte l'identifiant ET le mot de passe de la camera, en clair.
RE_SECRET_621 = re.compile(r'(621\|\d+\|\d+\|\d+\|\d+\|\d+\|[0-9A-Fa-f]{12}\|)[^|~"\\]*\|[^|~"\\]*')


def mask_secrets(text):
    return RE_SECRET_621.sub(r'\1***|***', text)


def mask(text):
    text = re.sub(r'("credential":")([0-9A-Fa-f]{8})[0-9A-Fa-f]+', r'\1\2...(masque)', text)
    return mask_secrets(text)


def _name_devidx(o):
    """Remplace partout 'devidx' (nombre) par le nom du carnet : 17 -> Salon (n.17)."""
    if isinstance(o, dict):
        for k, v in list(o.items()):
            if k == "devidx" and str(v).isdigit():
                o[k] = devname(v)
            else:
                _name_devidx(v)
    elif isinstance(o, list):
        for x in o:
            _name_devidx(x)


# Libelles pour decrire un /master/alarm/<type> en une phrase (section 12). Seul celui du type 8 est le
# libelle EXACT lu sur le vrai site (capture fournie par l'utilisateur, 25 octobre : "Alarme "Auto-protection"
# declenchee par votre IntelliTAG "<nom>"."). Les autres reprennent le nom du risque CERTAIN cote editeur de
# scenario (section 10, RISK_GROUPS) ; la phrase exacte affichee par le vrai site pour CES alarmes-la,
# precisement, n'a pas ete capturee -- [PROBABLE] seulement pour la formulation, pas pour le declencheur.
ALARM_LABELS = {
    8: "Auto-protection",
    2: "Intrusion",
    4: "Detection de fumee",
    16: "Signal de detresse",
    512: "Inondation",
    2048: "Alerte monoxyde de carbone",
}

# Seuil (en %) en dessous duquel un rapport de pile declenche "Niveau de batterie faible" (voir _learn(),
# recherche "bat" ci-dessous) -- demande le 4 novembre pour l'evenement pousse vers Jeedom (Event_Last).
BATTERY_LOW_THRESHOLD = 20


def describe_alarm(type_num, dev_label):
    """Phrase lisible pour un /master/alarm/<type_num> (None si le type n'est pas dans ALARM_LABELS)."""
    label = ALARM_LABELS.get(type_num)
    if label is None:
        return None
    return 'Alarme "%s" declenchee par %s.' % (label, dev_label)


def describe_environment(j):
    """Phrase lisible pour un /master/environment/ (temperature et/ou niveau d'alarme releves par
    une piece/un capteur, ex. {"devidx":"Salle cote jardin (n.11)","temp":"17.3","seclev":"desarme"})."""
    dev = j.get("devidx", "?")
    bits = []
    if j.get("temp") not in (None, ""):
        bits.append("%s°C" % str(j["temp"]).replace(".", ","))
    if j.get("seclev") not in (None, ""):
        bits.append(str(j["seclev"]))
    if not bits:
        return None
    return "%s : %s" % (dev, ", ".join(bits))


def summarize(body):
    """Resume lisible d'un message de la centrale (pour l'ecran)."""
    clean = body.replace('\\"', '"')
    m = re.search(r'"query":"(/master/\w+/?\d*)\?j=(\{.*\})"', clean)
    if m:
        try:
            j = json.loads(m.group(2))
            for k in NOISE_KEYS:
                j.pop(k, None)
            _name_devidx(j)
            if "seclev" in j:
                j["seclev"] = LEVELS.get(str(j["seclev"]), j["seclev"])
            am = re.match(r"/master/alarm/(\d+)$", m.group(1))
            if am:
                desc = describe_alarm(int(am.group(1)), j.get("devidx", "?"))
                if desc:
                    return desc
            if m.group(1).rstrip("/") == "/master/environment":
                desc = describe_environment(j)
                if desc:
                    return desc
            sm = re.match(r"/master/seclev/(\d+)$", m.group(1))
            if sm:
                return "Niveau d'alarme -> %s (origine : %s)" % (
                    LEVELS.get(sm.group(1), sm.group(1)), j.get("devidx", "?"))
            if m.group(1).rstrip("/") == "/master/new":
                devmod = j.get("devmod")
                return "Nouvel appareil detecte : %s%s" % (
                    j.get("devidx", "?"), (" (modele %s)" % devmod) if devmod else "")
            return "CALL %s %s" % (m.group(1), json.dumps(j, separators=(",", ":"), ensure_ascii=False))
        except ValueError:
            return "CALL %s %s" % (m.group(1), m.group(2)[:200])
    mp = re.match(r'PUSH \{ "state":"part", "content":(\d+)/', clean)
    if mp:                                # morceau de fichier : on n'affiche pas les octets bruts d'une photo
        return 'PUSH part (%s octets de donnees)' % mp.group(1)
    return mask(clean)[:220]


# Mis a True dans main() si jeedom_utils.set_log_level() a reussi (jeedom/jeedom.py present, --loglevel
# fourni par Jeedom) -- voir Log.line() ci-dessous. Sert UNIQUEMENT a eviter le doublon dans le fichier de
# log de Jeedom (deamon_start() redirige stdout ET stderr vers le MEME fichier : sans ce garde-fou, chaque
# evenement y apparaissait deux fois le 31 octobre -- une fois via print() [stdout, sans niveau], une fois
# via logging [stderr, avec niveau]). Reste False hors Jeedom : le print() continue de fonctionner
# normalement pour l'usage en ligne de commande (console interactive).
JEEDOM_LOGGING_ACTIVE = False


def _infer_log_level(text, show):
    """Deduit un niveau logging (DEBUG/INFO/WARNING/ERROR) a partir du texte -- Log.line() n'a jamais
    pris de niveau explicite (49 points d'appel, tous ecrits avant l'integration Jeedom), donc on
    reconnait les conventions deja utilisees dans le texte lui-meme plutot que de tout retagger a la
    main : prefixe "ATTENTION" (deja utilise pour les avertissements, ex. morceau de fichier incomplet),
    mots "IMPOSSIBLE"/"ERREUR"/"ECHEC"/"INVALIDE" (deja utilises pour les vraies erreurs -- port
    indisponible, connexion refusee, ecriture --pid...). Les messages routiniers (show=False, ex. les
    accuses de reception ordinaires) deviennent DEBUG : invisibles si Jeedom est regle au-dessus de ce
    niveau, exactement ce que fait deja --verbose pour la console."""
    if not show:
        return logging.DEBUG
    upper = text.upper()
    if any(k in upper for k in ("IMPOSSIBLE", "ERREUR", "ECHEC", "ÉCHEC", "INVALIDE")):
        return logging.ERROR
    if upper.lstrip().startswith("ATTENTION"):
        return logging.WARNING
    return logging.INFO


class Log(object):
    MAX = 5 * 1024 * 1024          # taille maximale avant rotation (2 sauvegardes conservees)

    def __init__(self, path):
        self.path = path
        self.f = open(path, "a", encoding="utf-8")
        self.lock = threading.Lock()
        self.n = 0

    def _rotate(self):
        self.f.close()
        for i in (1, 0):
            src = self.path + (".%d" % i if i else "")
            if os.path.exists(src):
                os.replace(src, "%s.%d" % (self.path, i + 1))
        self.f = open(self.path, "a", encoding="utf-8")

    def line(self, text, show=True):
        stamp = local_dt().strftime("%H:%M:%S")
        with self.lock:
            self.f.write("%s %s\n" % (local_dt().strftime("%Y-%m-%d %H:%M:%S"), text))
            self.f.flush()
            self.n += 1
            if self.n % 100 == 0 and os.path.getsize(self.path) > self.MAX:
                self._rotate()
            if show:
                RECENT_EVENTS.append((time.time(), text))
                if not JEEDOM_LOGGING_ACTIVE:
                    print("[%s] %s" % (stamp, text))
                    sys.stdout.flush()
        # Sous Jeedom (JEEDOM_LOGGING_ACTIVE, voir plus haut), c'est CETTE ligne -- et plus le print()
        # ci-dessus -- qui porte l'evenement dans le fichier de log du plugin : une seule fois, au format
        # Jeedom ("[date][NIVEAU] : message") sur stderr, avec le niveau qu'elle merite (_infer_log_level)
        # et donc correctement filtrable dans l'interface. Hors Jeedom, cet appel reste un no-op silencieux
        # (logger racine jamais configure) -- voir le commentaire de JEEDOM_LOGGING_ACTIVE.
        logging.log(_infer_log_level(text, show), text)



