# Libelles courts (utilises par les journaux, la base de connaissances et le journal en clair)
ORDER_LABELS = {code: court for (code, forme, court, detail, confiance, preuve) in ORDER_REFERENCE}


def print_reference():
    """Imprime la documentation complete (texte d'en-tete du fichier) puis le dictionnaire des ordres."""
    out = [__doc__ or "", "", "=" * 100, " DICTIONNAIRE DES ORDRES (serveur -> centrale)", "=" * 100]
    for code, forme, court, detail, confiance, preuve in ORDER_REFERENCE:
        out += ["", "  %-5s  %s" % (code, forme)]
        out += textwrap.wrap(detail, 96, initial_indent="         ", subsequent_indent="         ")
        out += ["         Confiance : %s" % confiance]
        out += textwrap.wrap("Preuve : %s" % preuve, 96, initial_indent="         ", subsequent_indent="                   ")
    text = "\n".join(out)
    try:
        print(text)
    except UnicodeEncodeError:            # terminal sans UTF-8 : on degrade plutot que de planter
        print(text.encode("ascii", "replace").decode("ascii"))


