def _is_local_ip(ip):
    """True pour une adresse du reseau local (privee, boucle locale, lien local, 100.64/10 de Tailscale...)."""
    try:
        a = ipaddress.ip_address(str(ip).split("%")[0])
    except ValueError:
        return False
    if getattr(a, "ipv4_mapped", None):
        a = a.ipv4_mapped
    return not a.is_global


