def order_perm(order):
    p = str(order).split("|")
    try:
        code = int(p[0])
    except ValueError:
        return "raw_order"
    if code == 100:
        try:
            return "disarm" if int(p[1], 16) == 1 else "arm"
        except (ValueError, IndexError):
            return "raw_order"
    return ORDER_PERMS.get(code, "raw_order")


def _slug(text):
    s = re.sub(r"[^a-z0-9]+", "-", str(text).lower()).strip("-")
    return s[:24] or "profil"


class Security(object):
    """Mot de passe du tableau de bord (facultatif), sessions, limitation des essais, verrou sur la centrale,
    journal d'audit. Tout est conserve dans le dossier de donnees : myfox_auth.json (mot de passe SALE ET HACHE,
    jamais en clair), myfox_security.json (verrou, adresses vues) et audit.log."""
    PBKDF2_ITER = 120000
    SESSION_SHORT = 12 * 3600
    SESSION_LONG = 30 * 86400
    MAX_FAILS = 5
    LOCK_SECONDS = 300
    AUDIT_MAX = 512 * 1024
    LOCAL_SUFFIXES = (".local", ".lan", ".home", ".home.arpa", ".internal", ".localdomain")

    def __init__(self, data_dir, log=None, allow_public=False, extra_hosts=None):
        self.data_dir = data_dir
        self.log = log
        self.allow_public = bool(allow_public)
        self.extra_hosts = set(h.strip().lower() for h in (extra_hosts or []) if h and h.strip())
        self.auth_path = os.path.join(data_dir, "myfox_auth.json")
        self.cfg_path = os.path.join(data_dir, "myfox_security.json")
        self.audit_path = os.path.join(data_dir, "audit.log")
        self.lock = threading.RLock()
        self.sessions = {}          # jeton -> (expiration, ip, compte)
        self.fails = {}             # ip -> [horodatages des echecs]
        self.locked = {}            # ip -> fin du blocage
        self.once = {}              # (ip, evenement) -> dernier horodatage journalise
        self.acct_path = os.path.join(data_dir, "myfox_accounts.json")
        self.acct = self._load(self.acct_path)
        self._ensure_roles()
        self.cfg = self._load(self.cfg_path)
        # migration : l'ancien mot de passe unique (myfox_auth.json) devient le compte "admin", super admin
        legacy = self._load(self.auth_path)
        if legacy.get("hash") and not self.users():
            self.users()["admin"] = {"name": "admin", "salt": legacy.get("salt", ""), "iter": legacy.get("iter", self.PBKDF2_ITER),
                                     "hash": legacy["hash"], "role": "superadmin", "created": legacy.get("date") or int(time.time())}
            self._save_acct()
            try:
                os.remove(self.auth_path)
            except OSError:
                pass
            self.audit("console", "MIGRATION", "mot de passe unique -> compte admin (super admin)")
        elif not os.path.exists(self.acct_path):
            self._save_acct()

    # ---- fichiers ----
    @staticmethod
    def _load(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                d = json.load(f)
            return d if isinstance(d, dict) else {}
        except (OSError, ValueError):
            return {}

    def _save(self, path, obj):
        try:
            os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
            tmp = path + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(obj, f, ensure_ascii=False, indent=1)
            try:
                os.chmod(tmp, 0o600)
            except OSError:
                pass
            os.replace(tmp, path)
        except OSError:
            pass

    # ---- comptes et profils ----
    def users(self):
        return self.acct.setdefault("users", {})

    def roles(self):
        return self.acct["roles"]

    def _save_acct(self):
        self._save(self.acct_path, self.acct)

    def _ensure_roles(self):
        roles = self.acct.setdefault("roles", {})
        for rid, r in DEFAULT_ROLES.items():
            if rid not in roles:
                roles[rid] = {"name": r["name"], "perms": list(r["perms"])}
        roles["superadmin"] = {"name": DEFAULT_ROLES["superadmin"]["name"], "perms": list(ALL_PERMS), "locked": True}
        for r in roles.values():
            r["perms"] = [p for p in r.get("perms", []) if p in PERM_LABEL]

    def has_password(self):
        """True des qu'un compte existe : le tableau de bord n'est plus ouvert."""
        return bool(self.users())

    def role_perms(self, rid):
        if rid == "superadmin":
            return set(ALL_PERMS)
        r = self.roles().get(rid)
        return set(r["perms"]) if r else set()

    def user_get(self, lname):
        return self.users().get(lname)

    def user_perms(self, lname):
        u = self.users().get(lname)
        return self.role_perms(u["role"]) if u else set()

    def _derive(self, pw, salt, iters):
        return hashlib.pbkdf2_hmac("sha256", pw.encode("utf-8"), salt, iters).hex()

    def _n_superadmins(self, excluding=None):
        return sum(1 for k, u in self.users().items() if u.get("role") == "superadmin" and k != excluding)

    def user_add(self, name, pw, role):
        name = str(name or "").strip()
        if not re.match(r"^[\w .@-]{1,32}$", name):
            return False, "Nom de compte invalide (1 à 32 caractères : lettres, chiffres, espace, . _ - @)."
        if len(pw) < 8 or len(pw) > 128:
            return False, "Le mot de passe doit avoir de 8 à 128 caractères."
        with self.lock:
            if name.lower() in self.users():
                return False, "Ce nom de compte existe déjà."
            if role not in self.roles():
                return False, "Profil inconnu."
            salt = os.urandom(16)
            self.users()[name.lower()] = {"name": name, "salt": salt.hex(), "iter": self.PBKDF2_ITER,
                                          "hash": self._derive(pw, salt, self.PBKDF2_ITER), "role": role, "created": int(time.time())}
            self._save_acct()
        return True, ""

    def user_password(self, lname, pw):
        if len(pw) < 8 or len(pw) > 128:
            return False, "Le mot de passe doit avoir de 8 à 128 caractères."
        with self.lock:
            u = self.users().get(lname)
            if not u:
                return False, "Compte inconnu."
            salt = os.urandom(16)
            u.update({"salt": salt.hex(), "iter": self.PBKDF2_ITER, "hash": self._derive(pw, salt, self.PBKDF2_ITER)})
            self._save_acct()
            self.end_user_sessions(lname)
        return True, ""

    def user_role(self, lname, role):
        with self.lock:
            u = self.users().get(lname)
            if not u:
                return False, "Compte inconnu."
            if role not in self.roles():
                return False, "Profil inconnu."
            if u["role"] == "superadmin" and role != "superadmin" and self._n_superadmins(excluding=lname) == 0:
                return False, "Il doit rester au moins un super admin."
            u["role"] = role
            self._save_acct()
        return True, ""

    def user_delete(self, lname):
        with self.lock:
            u = self.users().get(lname)
            if not u:
                return False, "Compte inconnu."
            if u["role"] == "superadmin" and self._n_superadmins(excluding=lname) == 0:
                return False, "Il doit rester au moins un super admin."
            del self.users()[lname]
            self._save_acct()
            self.end_user_sessions(lname)
        return True, ""

    def check_user(self, name, pw):
        """Compte (dict, avec cle 'lname') si le nom et le mot de passe sont bons, sinon None."""
        lname = str(name or "").strip().lower()
        u = self.users().get(lname)
        if not u:
            self._derive(str(pw), b"\0" * 16, self.PBKDF2_ITER)      # meme duree : ne revele pas si le compte existe
            return None
        try:
            calc = self._derive(str(pw), bytes.fromhex(u["salt"]), int(u.get("iter") or self.PBKDF2_ITER))
        except (ValueError, KeyError, TypeError):
            return None
        return dict(u, lname=lname) if hmac.compare_digest(calc, u.get("hash", "")) else None

    def remove_all(self):
        """Supprime tous les comptes et les cles d'integration : le tableau de bord redevient ouvert (profils conserves)."""
        with self.lock:
            self.acct["users"] = {}
            self._save_acct()
            self.sessions.clear()
            self.cfg.pop("disarm_password", None)
            self.cfg.pop("api_keys", None)
            self._save(self.cfg_path, self.cfg)

    # ---- profils ----
    def role_save(self, rid, name, perms):
        name = str(name or "").strip()
        if not name or len(name) > 30:
            return False, "Nom de profil invalide (1 à 30 caractères).", rid
        perms = [p for p in ALL_PERMS if p in (perms or [])]
        with self.lock:
            roles = self.roles()
            if rid:
                if rid == "superadmin":
                    return False, "Le profil Super admin n'est pas modifiable.", rid
                if rid not in roles:
                    return False, "Profil inconnu.", rid
            else:
                base = _slug(name)
                rid, n = base, 2
                while rid in roles:
                    rid, n = "%s-%d" % (base, n), n + 1
            if any(r.get("name", "").lower() == name.lower() and k != rid for k, r in roles.items()):
                return False, "Un profil porte déjà ce nom.", rid
            roles[rid] = {"name": name, "perms": perms}
            self._save_acct()
        return True, "", rid

    def role_delete(self, rid):
        with self.lock:
            if rid == "superadmin":
                return False, "Le profil Super admin ne peut pas être supprimé."
            if rid not in self.roles():
                return False, "Profil inconnu."
            if any(u.get("role") == rid for u in self.users().values()):
                return False, "Des comptes utilisent ce profil : changez-les d'abord."
            if any(self._key_role(e) == rid for e in (self.cfg.get("api_keys") or {}).values()):
                return False, "Des clés d'intégration utilisent ce profil."
            del self.roles()[rid]
            self._save_acct()
        return True, ""

    # ---- sessions et essais ----
    def new_session(self, ip, lname, long=False):
        ttl = self.SESSION_LONG if long else self.SESSION_SHORT
        tok = secrets.token_urlsafe(32)
        now = time.time()
        with self.lock:
            for k in [k for k, v in self.sessions.items() if v[0] < now]:
                del self.sessions[k]
            if len(self.sessions) >= 100:
                del self.sessions[min(self.sessions, key=lambda k: self.sessions[k][0])]
            self.sessions[tok] = (now + ttl, ip, lname)
        return tok, ttl

    def session_user(self, tok):
        """Nom (minuscules) du compte de cette session, ou None si elle est inconnue, expiree ou si le compte a disparu."""
        if not tok:
            return None
        with self.lock:
            v = self.sessions.get(tok)
            if not v:
                return None
            if v[0] < time.time() or v[2] not in self.users():
                self.sessions.pop(tok, None)
                return None
            return v[2]

    def session_ok(self, tok):
        return self.session_user(tok) is not None

    def end_session(self, tok):
        with self.lock:
            self.sessions.pop(tok, None)

    def end_user_sessions(self, lname):
        with self.lock:
            for k in [k for k, v in self.sessions.items() if v[2] == lname]:
                del self.sessions[k]

    def throttle(self, ip):
        """Secondes restantes de blocage pour cette adresse (0 si libre)."""
        with self.lock:
            until = self.locked.get(ip, 0)
        rest = int(until - time.time())
        return rest if rest > 0 else 0

    def record_fail(self, ip):
        now = time.time()
        with self.lock:
            lst = [t for t in self.fails.get(ip, []) if now - t < 600] + [now]
            if len(lst) >= self.MAX_FAILS:
                self.locked[ip] = now + self.LOCK_SECONDS
                lst = []
                self.audit(ip, "BLOCAGE", "%d echecs : adresse bloquee %d min" % (self.MAX_FAILS, self.LOCK_SECONDS // 60))
            self.fails[ip] = lst

    def clear_fail(self, ip):
        with self.lock:
            self.fails.pop(ip, None)
            self.locked.pop(ip, None)

    # ---- controles d'acces ----
    def client_ok(self, ip):
        return self.allow_public or _is_local_ip(ip)

    def host_ok(self, host):
        """Contre le 'DNS rebinding' : l'en-tete Host doit etre une adresse IP, un nom court (sans point),
        un nom local (.local, .lan...) ou un nom ajoute avec --allow-host."""
        h = (host or "").strip().lower()
        if not h:
            return True
        if h.startswith("["):
            name = h[1:h.find("]")] if "]" in h else h
        else:
            name = h.rsplit(":", 1)[0] if re.search(r":\d+$", h) else h
        try:
            ipaddress.ip_address(name)
            return True
        except ValueError:
            pass
        if "." not in name or name in self.extra_hosts:
            return True
        return name.endswith(self.LOCAL_SUFFIXES)

    # ---- journal d'audit ----
    def audit(self, ip, event, detail=""):
        det = re.sub(r"[\r\n|]+", " ", str(detail))[:200]
        line = "%s | %s | %s | %s\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), ip or "-", event, det)
        with self.lock:
            try:
                if os.path.exists(self.audit_path) and os.path.getsize(self.audit_path) > self.AUDIT_MAX:
                    os.replace(self.audit_path, self.audit_path + ".1")
                with open(self.audit_path, "a", encoding="utf-8") as f:
                    f.write(line)
            except OSError:
                pass

    def audit_once(self, ip, event, detail="", every=600):
        """Comme audit() mais au plus une fois par 'every' secondes et par (adresse, evenement) : pas de bourrage du journal."""
        now = time.time()
        with self.lock:
            if now - self.once.get((ip, event), 0) < every:
                return
            self.once[(ip, event)] = now
        self.audit(ip, event, detail)

    def audit_tail(self, n=40):
        try:
            with open(self.audit_path, "rb") as f:
                f.seek(0, os.SEEK_END)
                size = f.tell()
                f.seek(max(0, size - 65536))
                data = f.read().decode("utf-8", "replace")
        except OSError:
            return []
        return list(reversed(data.splitlines()[-n:]))

    # ---- centrale (port 8888) ----
    def panel_connect(self, ip):
        """Appele a chaque connexion sur le port de la centrale ; False = connexion a refuser."""
        if not (self.client_ok(ip)):
            self.audit_once(ip, "CENTRALE_REFUSEE", "adresse non locale")
            return False
        lock = self.cfg.get("panel_lock") or ""
        # 127.0.0.1/::1 exemptes du verrou : avec --guard-port (myfox_tcp_guard.py, voir plus bas), le
        # backend n'est plus contacte directement par la centrale mais par le garde TCP local -- un
        # verrou configure sur l'ancienne IP LAN de la centrale bloquerait alors TOUT (y compris apres
        # redemarrage du backend), car la connexion entrante vient desormais systematiquement de
        # loopback. Le loopback n'est de toute facon jamais une IP externe a verrouiller.
        if lock and ip != lock and ip not in ("127.0.0.1", "::1"):
            self.audit_once(ip, "CENTRALE_REFUSEE", "verrou actif sur %s" % lock)
            return False
        with self.lock:
            seen = self.cfg.setdefault("panel_seen", {})
            e = seen.setdefault(ip, {"first": int(time.time()), "count": 0})
            e["last"] = int(time.time())
            e["count"] = int(e.get("count", 0)) + 1
            while len(seen) > 8:
                del seen[min(seen, key=lambda k: seen[k].get("last", 0))]
            self._save(self.cfg_path, self.cfg)
        return True

    def panel_current(self):
        seen = self.cfg.get("panel_seen") or {}
        return max(seen, key=lambda k: seen[k].get("last", 0)) if seen else ""

    def panel_lock(self, ip, dhcp_ok):
        seen = self.cfg.get("panel_seen") or {}
        if not dhcp_ok:
            return False, "Cochez d'abord la confirmation de la reservation DHCP."
        if ip not in seen:
            return False, "Cette adresse n'a jamais ete vue sur le port de la centrale."
        with self.lock:
            self.cfg["panel_lock"] = ip
            self.cfg["dhcp_confirmed"] = int(time.time())
            self._save(self.cfg_path, self.cfg)
        return True, "Port de la centrale verrouille sur %s." % ip

    def panel_unlock(self):
        with self.lock:
            self.cfg.pop("panel_lock", None)
            self.cfg.pop("dhcp_confirmed", None)
            self._save(self.cfg_path, self.cfg)

    def set_option(self, name, on):
        with self.lock:
            if on:
                self.cfg[name] = True
            else:
                self.cfg.pop(name, None)
            self._save(self.cfg_path, self.cfg)

    # ---- cles d'integration (Jeedom, Home Assistant...) : jetons longs, stockes hachees (SHA-256), chacun avec un profil ----
    MAX_KEYS = 20

    def _key_role(self, e):
        return e.get("role") or ("invite" if e.get("ro") else "admin")

    def key_perms(self, e):
        return self.role_perms(self._key_role(e)) - set(KEY_FORBIDDEN)

    def key_create(self, name, role):
        if role not in self.roles() or (self.role_perms(role) & set(KEY_FORBIDDEN)):
            return None, None
        tok = "mfx_" + secrets.token_urlsafe(32)
        kid = secrets.token_hex(4)
        with self.lock:
            keys = self.cfg.setdefault("api_keys", {})
            if len(keys) >= self.MAX_KEYS:
                return None, None
            keys[kid] = {"name": str(name)[:40] or "sans nom", "hash": hashlib.sha256(tok.encode("utf-8")).hexdigest(),
                         "role": role, "created": int(time.time()), "last": 0, "ip": ""}
            self._save(self.cfg_path, self.cfg)
        return kid, tok

    def key_revoke(self, kid):
        with self.lock:
            e = (self.cfg.get("api_keys") or {}).pop(str(kid), None)
            if e is not None:
                self._save(self.cfg_path, self.cfg)
        return e

    def key_check(self, tok, ip):
        """Entree de la cle (dict) si 'tok' est une cle d'integration valide, sinon None."""
        if not tok or not str(tok).startswith("mfx_"):
            return None
        h = hashlib.sha256(str(tok).encode("utf-8")).hexdigest()
        with self.lock:
            for kid, e in (self.cfg.get("api_keys") or {}).items():
                if hmac.compare_digest(h, e.get("hash", "")):
                    now = int(time.time())
                    if now - int(e.get("last", 0)) > 60 or e.get("ip") != ip:
                        e["last"], e["ip"] = now, ip
                        self._save(self.cfg_path, self.cfg)
                    return dict(e, id=kid, role=self._key_role(e))
        return None

    def disarm_needs_password(self):
        return bool(self.cfg.get("disarm_password")) and self.has_password()

    def public_state(self):
        return {"auth": self.has_password(), "disarm_pw": self.disarm_needs_password(),
                "lock": self.cfg.get("panel_lock") or ""}

    def state_for(self, perms, me):
        """Etat de securite montre a l'appelant : chaque partie n'est donnee que si ses droits le permettent."""
        st = {"auth": self.has_password(), "disarm_pw": self.disarm_needs_password(), "me": me,
              "perm_groups": [[g, [[k, l] for k, l in items]] for g, items in PERMS]}
        if "view_audit" in perms:
            st["audit"] = self.audit_tail(40)
        if "admin" in perms:
            seen = self.cfg.get("panel_seen") or {}
            st["panel"] = {"seen": sorted(({"ip": k, "last": v.get("last", 0), "count": v.get("count", 0)}
                                           for k, v in seen.items()), key=lambda x: -x["last"]),
                           "lock": self.cfg.get("panel_lock") or "", "dhcp_at": self.cfg.get("dhcp_confirmed", 0),
                           "current": self.panel_current()}
            st["keys"] = sorted(({"id": k, "name": v.get("name", ""), "role": self._key_role(v), "created": v.get("created", 0),
                                  "last": v.get("last", 0), "ip": v.get("ip", "")}
                                 for k, v in (self.cfg.get("api_keys") or {}).items()), key=lambda x: x["created"])
            st["key_roles"] = [{"id": r, "name": self.roles()[r]["name"]} for r in self.role_order()
                               if not (self.role_perms(r) & set(KEY_FORBIDDEN))]
            st["allow_public"] = self.allow_public
        if "accounts" in perms:
            st["users"] = sorted(({"name": u["name"], "role": u["role"], "created": u.get("created", 0)}
                                  for u in self.users().values()), key=lambda x: x["name"].lower())
            st["roles"] = {r: {"name": self.roles()[r]["name"], "perms": sorted(self.role_perms(r)),
                               "locked": r == "superadmin"} for r in self.role_order()}
            st["role_order"] = self.role_order()
        return st

    def role_order(self):
        rest = sorted((r for r in self.roles() if r not in ROLE_ORDER), key=lambda r: self.roles()[r]["name"].lower())
        return [r for r in ROLE_ORDER if r in self.roles()] + rest


def _is_disarm_order(order):
    """True pour l'ordre de desarmement : 100|1."""
    p = str(order).split("|")
    try:
        return int(p[0]) == 100 and len(p) > 1 and p[1] != "" and int(p[1], 16) == 1
    except ValueError:
        return False


