class DashboardHandler(http.server.BaseHTTPRequestHandler):
    server_version = "MyfoxLocal/1.0"

    def log_message(self, fmt, *args):
        pass        # le journal principal suffit ; on evite de polluer la console avec chaque requete HTTP

    def end_headers(self):
        # en-tetes de durcissement, ajoutes a TOUTES les reponses
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header("Referrer-Policy", "no-referrer")
        http.server.BaseHTTPRequestHandler.end_headers(self)

    def _send_json(self, obj, code=200, headers=None):
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        for k, v in (headers or {}).items():
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(body)

    CSP = ("default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; "
           "img-src 'self' data: blob:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'")

    def _send_html(self, text):
        body = text.encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Content-Security-Policy", self.CSP)
        self.end_headers()
        self.wfile.write(body)

    # ---- securite : garde appelee en tete de do_GET / do_POST ----
    PUBLIC_PATHS = ("/login", "/api/login")

    @staticmethod
    def _is_cloud2_path(path):
        """Chemins de l'emulation locale de l'API cloud (section "EMULATION LOCALE DE L'API CLOUD") :
        /oauth2/token (jeton), et /v2/, /client/, /site/ (routes REST), tous proteges par leur propre
        cle API (cloud2_issue_token/cloud2_check_token), pas par le systeme de comptes du tableau de
        bord -- voir le commentaire dans _guard()."""
        return path == "/oauth2/token" or path.startswith(("/v2/", "/client/", "/site/"))

    def _cookie_token(self):
        auth = self.headers.get("Authorization") or ""
        if auth.lower().startswith("bearer "):
            return auth[7:].strip()
        try:
            c = http.cookies.SimpleCookie(self.headers.get("Cookie") or "")
            return c["mfx_session"].value if "mfx_session" in c else None
        except http.cookies.CookieError:
            return None

    def _session_cookie(self, tok, ttl):
        return {"Set-Cookie": "mfx_session=%s; Path=/; Max-Age=%d; HttpOnly; SameSite=Strict" % (tok, ttl)}

    def _guard(self, method, path):
        """True si la requete peut continuer ; sinon la reponse (refus, 401 ou redirection) est deja envoyee.
        Renseigne aussi l'appelant : self._user (nom), self._role (profil), self._perms (droits)."""
        sec = SEC
        self._token = None
        self._apikey = None
        self._lname = None
        self._user = ""
        self._role = ""
        self._perms = set(ALL_PERMS)
        if sec is None:
            return True
        ip = self.client_address[0]
        if not sec.client_ok(ip):
            sec.audit_once(ip, "REFUS_ADRESSE", "adresse non locale")
            self._send_json({"error": "acces refuse"}, 403)
            return False
        if not sec.host_ok(self.headers.get("Host", "")):
            sec.audit_once(ip, "REFUS_NOM_HOTE", (self.headers.get("Host") or "")[:80])
            self._send_json({"error": "nom d'hote refuse (voir l'option --allow-host)"}, 403)
            return False
        if method == "POST":
            host = (self.headers.get("Host") or "").strip().lower()
            for hdr in ("Origin", "Referer"):
                v = self.headers.get(hdr)
                if v:
                    if urllib.parse.urlparse(v).netloc.lower() != host:
                        sec.audit_once(ip, "REFUS_ORIGINE", "%s: %s" % (hdr, v[:80]))
                        self._send_json({"error": "origine refusee"}, 403)
                        return False
                    break
        # L'emulation locale de l'API cloud (/v2/, /client/, /site/, /oauth2/token -- voir "EMULATION
        # LOCALE DE L'API CLOUD" plus haut) a sa PROPRE authentification (cle API cloud2, verifiee par
        # _cloud2_auth()/cloud2_issue_token(), independante des comptes du tableau de bord) : elle reste
        # donc accessible meme quand un mot de passe de tableau de bord est defini, pour ne pas casser
        # les clients REST existants (ex. plugin Jeedom AlarmeMyfox) qui n'ont que cette cle.
        if self._is_cloud2_path(path) or not sec.has_password() or path in self.PUBLIC_PATHS:
            return True                       # tableau de bord ouvert : tous les droits (bandeau d'avertissement dans la page)
        tok = self._cookie_token()
        ln = sec.session_user(tok)
        if ln:
            u = sec.user_get(ln)
            self._token, self._lname, self._user, self._role = tok, ln, u["name"], u["role"]
            self._perms = sec.user_perms(ln)
            return True
        key = sec.key_check(tok, ip)
        if key:
            # cle d'integration : droits de son profil (sans administration) ; jamais les reglages de securite
            if path.startswith("/api/security") or path.startswith("/api/auth/") or path == "/api/logout":
                sec.audit_once(ip, "REFUS_CLE", "%s %s (cle %s)" % (method, path, key.get("name", "")))
                self._send_json({"error": "reserve a une session de connexion"}, 403)
                return False
            self._apikey = key
            self._user, self._role = "cle:" + key.get("name", ""), key["role"]
            self._perms = sec.key_perms(key)
            return True
        if method == "GET" and "text/html" in (self.headers.get("Accept") or ""):
            nxt = self.path if self.path.startswith("/") and not self.path.startswith("//") else "/"
            self.send_response(302)
            self.send_header("Location", "/login?next=" + urllib.parse.quote(nxt, safe=""))
            self.send_header("Content-Length", "0")
            self.end_headers()
            return False
        self._send_json({"error": "authentification requise", "login": "/login"}, 401)
        return False

    def _need(self, perm):
        """True si l'appelant a ce droit ; sinon repond 403 et renvoie False."""
        if perm in self._perms:
            return True
        if SEC:
            SEC.audit_once(self.client_address[0], "REFUS_DROIT", "%s : %s" % (self._user or "?", perm), every=60)
        self._send_json({"error": "Action non autorisée pour votre profil : %s." % PERM_LABEL.get(perm, perm), "need": perm}, 403)
        return False

    def _me(self):
        sec = SEC
        if sec is None or not sec.has_password():
            return {"open": True, "name": "", "role": "", "role_name": "", "perms": sorted(self._perms)}
        rn = (sec.roles().get(self._role) or {}).get("name", self._role)
        return {"open": False, "name": self._user, "role": self._role, "role_name": rn,
                "key": bool(self._apikey), "perms": sorted(self._perms)}

    def _login_page(self):
        sec = SEC
        if sec is None or not sec.has_password() or sec.session_ok(self._cookie_token()):
            self.send_response(302)
            self.send_header("Location", "/")
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        self._send_html(LOGIN_HTML)

    def _who(self):
        return "%s [%s]" % (self.client_address[0], self._user) if getattr(self, "_user", "") else self.client_address[0]

    def _check_pw(self, ip, pw):
        """Verifie le mot de passe du compte connecte (limitation des essais incluse). Repond lui-meme en cas d'echec."""
        sec = SEC
        wait = sec.throttle(ip)
        if wait:
            self._send_json({"error": "Trop d'essais : reessayez dans %d s." % wait}, 429)
            return False
        if self._lname and sec.check_user(self._lname, str(pw or "")):
            sec.clear_fail(ip)
            return True
        sec.record_fail(ip)
        sec.audit(self._who(), "ECHEC_MOT_DE_PASSE", self.path)
        time.sleep(0.6)
        self._send_json({"error": "Mot de passe incorrect."}, 403)
        return False

    def _fail(self, msg, code=400):
        self._send_json({"ok": False, "error": msg}, code)

    def _post_security(self, path, data):
        """Routes de connexion, de comptes, de profils et de reglages de securite. True si la requete a ete traitee ici."""
        sec = SEC
        if sec is None or not (path in ("/api/login", "/api/logout") or path.startswith("/api/auth/")
                               or path.startswith("/api/security/")):
            return False
        ip = self.client_address[0]
        if path == "/api/login":
            if not sec.has_password():
                self._send_json({"ok": True, "open": True})
                return True
            wait = sec.throttle(ip)
            if wait:
                self._send_json({"error": "Trop d'essais : reessayez dans %d s." % wait}, 429)
                return True
            name = str(data.get("name", "")).strip()
            if not name and len(sec.users()) == 1:
                name = next(iter(sec.users().values()))["name"]
            u = sec.check_user(name, str(data.get("password", "")))
            if u:
                sec.clear_fail(ip)
                lng = bool(data.get("remember"))
                tok, ttl = sec.new_session(ip, u["lname"], lng)
                sec.audit("%s [%s]" % (ip, u["name"]), "CONNEXION", "session de %s" % ("30 jours" if lng else "12 h"))
                self._send_json({"ok": True, "token": tok, "name": u["name"], "role": u["role"]}, headers=self._session_cookie(tok, ttl))
            else:
                sec.record_fail(ip)
                sec.audit(ip, "ECHEC_CONNEXION", name[:32])
                time.sleep(0.6)
                self._send_json({"error": "Nom ou mot de passe incorrect."}, 401)
            return True
        if path == "/api/logout":
            if self._token:
                sec.end_session(self._token)
            sec.audit(self._who(), "DECONNEXION", "")
            self._send_json({"ok": True}, headers=self._session_cookie("", 0))
            return True
        if path == "/api/auth/set":
            pw = str(data.get("password", ""))
            if not sec.has_password():
                # premier compte : super admin
                name = str(data.get("name") or "admin").strip()
                ok, msg = sec.user_add(name, pw, "superadmin")
                if not ok:
                    self._fail(msg)
                    return True
                tok, ttl = sec.new_session(ip, name.lower())
                sec.audit("%s [%s]" % (ip, name), "COMPTE_CREE", "%s (super admin, premier compte)" % name)
                self._send_json({"ok": True}, headers=self._session_cookie(tok, ttl))
                return True
            if not self._lname:
                self._fail("Connectez-vous avec un compte pour changer son mot de passe.", 403)
                return True
            if not self._check_pw(ip, data.get("current", "")):
                return True
            ok, msg = sec.user_password(self._lname, pw)
            if not ok:
                self._fail(msg)
                return True
            tok, ttl = sec.new_session(ip, self._lname)
            sec.audit(self._who(), "MOT_DE_PASSE_CHANGE", "")
            self._send_json({"ok": True}, headers=self._session_cookie(tok, ttl))
            return True
        if path == "/api/auth/remove":
            if not sec.has_password():
                self._send_json({"ok": True})
                return True
            if not self._need("accounts") or not self._check_pw(ip, data.get("password", "")):
                return True
            sec.remove_all()
            sec.audit(self._who(), "PROTECTION_RETIREE", "tous les comptes et les cles sont supprimes : le tableau de bord est ouvert")
            self._send_json({"ok": True}, headers=self._session_cookie("", 0))
            return True
        if path == "/api/security/accounts":
            if not self._need("accounts"):
                return True
            act, name = data.get("action"), str(data.get("name", "")).strip()
            ln = name.lower()
            if act == "create":
                ok, msg = sec.user_add(name, str(data.get("password", "")), str(data.get("role", "")))
                if ok:
                    sec.audit(self._who(), "COMPTE_CREE", "%s (%s)" % (name, data.get("role")))
            elif act == "delete":
                ok, msg = (False, "Vous ne pouvez pas supprimer votre propre compte.") if ln == self._lname else sec.user_delete(ln)
                if ok:
                    sec.audit(self._who(), "COMPTE_SUPPRIME", name)
            elif act == "password":
                ok, msg = (False, "Pour changer votre propre mot de passe, utilisez « Mon compte ».") if ln == self._lname \
                    else sec.user_password(ln, str(data.get("password", "")))
                if ok:
                    sec.audit(self._who(), "MOT_DE_PASSE_REINITIALISE", name)
            elif act == "role":
                ok, msg = sec.user_role(ln, str(data.get("role", "")))
                if ok:
                    sec.audit(self._who(), "COMPTE_PROFIL", "%s -> %s" % (name, data.get("role")))
            else:
                ok, msg = False, "action inconnue"
            self._send_json({"ok": True} if ok else {"ok": False, "error": msg}, 200 if ok else 400)
            return True
        if path == "/api/security/roles":
            if not self._need("accounts"):
                return True
            act = data.get("action")
            if act == "save":
                ok, msg, rid = sec.role_save(data.get("id") or None, data.get("name"), data.get("perms") or [])
                if ok:
                    sec.audit(self._who(), "PROFIL_ENREGISTRE", "%s (%d droits)" % (data.get("name"), len(data.get("perms") or [])))
                self._send_json({"ok": True, "id": rid} if ok else {"ok": False, "error": msg}, 200 if ok else 400)
            elif act == "delete":
                ok, msg = sec.role_delete(str(data.get("id", "")))
                if ok:
                    sec.audit(self._who(), "PROFIL_SUPPRIME", str(data.get("id", "")))
                self._send_json({"ok": True} if ok else {"ok": False, "error": msg}, 200 if ok else 400)
            else:
                self._fail("action inconnue")
            return True
        if path == "/api/security/key":
            if not self._need("admin"):
                return True
            if not sec.has_password():
                self._fail("Creez d'abord un compte (onglet Securite).")
            elif data.get("action") == "create":
                kid, tok = sec.key_create(str(data.get("name", "")).strip(), str(data.get("role", "")))
                if not kid:
                    self._fail("Profil refuse pour une cle (pas de droits d'administration) ou nombre maximal de cles atteint (%d)." % sec.MAX_KEYS)
                else:
                    sec.audit(self._who(), "CLE_CREEE", "%s (profil %s)" % (str(data.get("name", ""))[:40], data.get("role")))
                    self._send_json({"ok": True, "id": kid, "token": tok})
            elif data.get("action") == "revoke":
                e = sec.key_revoke(data.get("id", ""))
                if e is not None:
                    sec.audit(self._who(), "CLE_REVOQUEE", e.get("name", ""))
                self._send_json({"ok": e is not None})
            else:
                self._fail("action inconnue")
            return True
        if path == "/api/security/option":
            if not self._need("admin"):
                return True
            on = bool(data.get("on"))
            if data.get("name") != "disarm_password":
                self._fail("option inconnue")
            elif on and not sec.has_password():
                self._fail("Creez d'abord un compte.")
            else:
                sec.set_option("disarm_password", on)
                sec.audit(self._who(), "OPTION_DESARMEMENT", "mot de passe %s" % ("exige" if on else "non exige"))
                self._send_json({"ok": True})
            return True
        if path == "/api/security/panel":
            if not self._need("admin"):
                return True
            if data.get("action") == "unlock":
                sec.panel_unlock()
                sec.audit(self._who(), "VERROU_CENTRALE_RETIRE", "")
                self._send_json({"ok": True, "message": "Verrou retire."})
            elif data.get("action") == "lock":
                target = str(data.get("ip") or sec.panel_current())
                ok, msg = sec.panel_lock(target, data.get("dhcp") is True)
                if ok:
                    sec.audit(self._who(), "VERROU_CENTRALE", target)
                self._send_json({"ok": ok, "message": msg}, 200 if ok else 400)
            else:
                self._fail("action inconnue")
            return True
        self._send_json({"error": "not found"}, 404)
        return True

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        if not self._guard("GET", parsed.path):
            return
        gp = GET_PERMS.get(parsed.path)
        if gp and not self._need(gp):
            return
        if parsed.path == "/login":
            self._login_page()
        elif parsed.path == "/api/security":
            self._send_json(SEC.state_for(self._perms, self._me()) if SEC else {"auth": False})
        elif parsed.path in ("/", "/index.html"):
            self._send_html(DASHBOARD_HTML)
        elif parsed.path == "/api/state":
            _st = web_build_state()
            _st["me"] = self._me()
            self._send_json(_st)
        elif parsed.path == "/api/notify":
            if NOTIFIER is None:
                self._send_json({"error": "notifications indisponibles"}, 503)
            else:
                self._send_json({"config": NOTIFIER.public_config(), "schema": NOTIFIER.schema(),
                                 "history": list(reversed(NOTIFIER.history[-15:])),
                                 "learning": bool(WEB_LEARNER_REF)})
        elif parsed.path == "/api/update":
            self._send_json(UPDATER.info() if UPDATER else {"current": APP_VERSION, "enabled": False, "newer": False})
        elif parsed.path == "/api/cloud":
            self._send_json(web_build_cloud())
        elif parsed.path == "/api/scenario":
            qs = urllib.parse.parse_qs(parsed.query)
            ident = (qs.get("id") or [""])[0]
            learner = WEB_LEARNER_REF
            if not ident.isdigit() or not learner:
                self._send_json({"error": "identifiant invalide"}, 400)
                return
            tabs = learner.kb.get("scenario_tables", {}).get(ident)
            if not tabs:
                self._send_json({"error": "scenario inconnu (jamais vu passer sur le relais)"}, 404)
                return
            self._send_json({"ok": True, "spec": parse_scenario_spec(tabs[-1]["t1"])})
        elif parsed.path == "/api/video/live":
            self.send_response(200)
            self.send_header("Content-Type", "multipart/x-mixed-replace; boundary=frame")
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            last = 0
            idle_since = time.time()
            try:
                while True:
                    with LIVE.cond:
                        LIVE.cond.wait_for(lambda: LIVE.n != last or not LIVE.active, timeout=2.0)
                        frame, n, active = LIVE.frame, LIVE.n, LIVE.active
                    if n != last and frame:
                        last = n
                        idle_since = time.time()
                        self.wfile.write(b"--frame\r\nContent-Type: image/jpeg\r\nContent-Length: %d\r\n\r\n" % len(frame))
                        self.wfile.write(frame)
                        self.wfile.write(b"\r\n")
                        self.wfile.flush()
                    elif not active and time.time() - idle_since > 3:
                        break
            except (OSError, socket.error):
                pass
        elif parsed.path == "/api/photos":
            self._send_json({"photos": list_photos()})
        elif parsed.path == "/api/photo/file":
            _q = urllib.parse.parse_qs(parsed.query)
            pp = photo_path((_q.get("name") or [""])[0])
            if not pp:
                self._send_json({"error": "photo inconnue"}, 404)
                return
            # Ouverte dans un onglet (navigation : Accept contient text/html) : page avec zoom ; en <img> ou avec
            # raw=1 : le fichier JPEG d'origine. L'agrandissement et la netteté sont calculés par le navigateur.
            if "text/html" in (self.headers.get("Accept") or "") and not _q.get("raw"):
                self._send_html(PHOTO_VIEWER_HTML)
                return
            with open(pp, "rb") as f:
                body = f.read()
            self.send_response(200)
            self.send_header("Content-Type", "image/jpeg")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(body)
        elif parsed.path == "/api/photo/latest":
            lp = latest_photo()
            if not lp:
                self._send_json({"error": "aucune photo"}, 404)
                return
            if "text/html" in (self.headers.get("Accept") or "") and not urllib.parse.parse_qs(parsed.query).get("raw"):
                self._send_html(PHOTO_VIEWER_HTML)       # ouverte dans un onglet : page avec zoom (voir /api/photo/file)
                return
            with open(lp, "rb") as f:
                body = f.read()
            self.send_response(200)
            self.send_header("Content-Type", "image/jpeg")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(body)
        elif parsed.path in ("/api/video/latest", "/api/video/frame"):
            frame = parsed.path.endswith("frame")
            vp = latest_video_frame() if frame else latest_video()
            if not vp:
                self._send_json({"error": "aucun flux"}, 404)
                return
            with open(vp, "rb") as f:
                body = f.read()
            self.send_response(200)
            self.send_header("Content-Type", "image/jpeg" if frame else "application/octet-stream")
            if not frame:
                self.send_header("Content-Disposition", 'attachment; filename="%s"' % os.path.basename(vp))
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(body)
        elif parsed.path == "/api/history":
            qs = urllib.parse.parse_qs(parsed.query)
            try:
                n = max(1, min(5000, int(qs.get("n", ["60"])[0])))
                minutes = max(0, min(1440, int(qs.get("minutes", ["0"])[0])))
            except ValueError:
                n, minutes = 60, 0
            ev, cut = web_build_history(n, minutes)
            self._send_json({"events": ev, "truncated": cut})
        elif parsed.path.startswith("/v2/") or parsed.path.startswith("/client/") or parsed.path.startswith("/site/"):
            self._cloud2_get(parsed)
        else:
            self._send_json({"error": "not found"}, 404)

    def _cloud2_auth(self, parsed):
        """Verifie ?access_token= sur une requete de l'emulation cloud (voir "EMULATION LOCALE DE L'API
        CLOUD" plus haut). Envoie elle-meme la reponse d'erreur et renvoie False si le jeton est absent/
        invalide/expire -- a l'image du vrai api.myfox.me qui renvoie un code HTTP d'erreur dans ce cas."""
        token = (urllib.parse.parse_qs(parsed.query).get("access_token") or [""])[0]
        if not cloud2_check_token(token):
            self._send_json({"status": "KO", "error": "Invalid or expired access_token."}, 401)
            return False
        return True

    def _cloud2_get(self, parsed):
        if not self._cloud2_auth(parsed):
            return
        found, payload = cloud2_dispatch_path(parsed.path)
        self._send_json(payload, 200 if found else 404)

    AUDITED_POSTS = ("/api/identity", "/api/camera/install", "/api/relay", "/api/photo/delete", "/api/video/delete",
                     "/api/camera/privacy", "/api/photo/retention", "/api/scenario", "/api/scenario/toggle",
                     "/api/notify", "/api/notify/test", "/api/update", "/api/update/check")

    def do_POST(self):
        parsed = urllib.parse.urlparse(self.path)
        if not self._guard("POST", parsed.path):
            return
        length = int(self.headers.get("Content-Length", 0))
        if length > 8 * 1024 * 1024:
            self._send_json({"error": "requete trop grande"}, 413)
            return
        raw = self.rfile.read(length) if length else b""
        if parsed.path == "/oauth2/token":
            # Jeton de l'emulation cloud (section "EMULATION LOCALE DE L'API CLOUD") : forme OAuth2
            # classique (form-urlencoded ou multipart), PAS du JSON -- traite avant le parsing JSON
            # ci-dessous qui ne s'applique qu'aux routes /api/... de ce tableau de bord.
            ctype = self.headers.get("Content-Type", "")
            fields = {}
            if "multipart/form-data" in ctype:
                bm = re.search(r"boundary=(.+)", ctype)
                boundary = bm.group(1).strip('"') if bm else None
                if boundary:
                    for part in raw.split(("--" + boundary).encode("ascii", "replace")):
                        part = part.strip(b"\r\n-")
                        if not part:
                            continue
                        head, sep, body = part.partition(b"\r\n\r\n")
                        nm = re.search(rb'name="([^"]*)"', head)
                        if nm and sep:
                            fields[nm.group(1).decode("utf-8", "replace")] = body.rstrip(b"\r\n").decode("utf-8", "replace")
            else:
                for k, v in urllib.parse.parse_qs(raw.decode("utf-8", "replace")).items():
                    fields[k] = v[0] if v else ""
            resp = cloud2_issue_token(fields.get("client_id", ""), fields.get("client_secret", ""))
            self._send_json(resp, 200 if "access_token" in resp else 400)
            return
        try:
            data = json.loads(raw.decode("utf-8")) if raw else {}
        except ValueError:
            self._send_json({"error": "json invalide"}, 400)
            return
        if not isinstance(data, dict):
            data = {}
        if self._post_security(parsed.path, data):
            return
        if SEC and (parsed.path in self.AUDITED_POSTS or parsed.path.startswith("/api/cloud/")):
            SEC.audit(self._who(), "ACTION", parsed.path)
        _pp = POST_PERMS.get(parsed.path) or ("identity" if parsed.path.startswith("/api/cloud/") else None)
        if _pp and not self._need(_pp):
            return
        if parsed.path == "/api/order":
            order = str(data.get("order", ""))
            # Forme generale : un code numerique puis des arguments separes par "|". La plupart des ordres
            # connus n'utilisent que des chiffres/hexa, mais l'ordre 621 (camera : creation/association,
            # voir ORDER_REFERENCE "621") transporte aussi un nom choisi par l'utilisateur et un nom de
            # serveur NTP -- on autorise donc tout caractere imprimable dans chaque argument, SAUF ceux qui
            # casseraient l'encodage JSON manuel de send_order() (guillemet, antislash) ou la trame elle-meme
            # ("|" = separateur de champs, "~" = terminateur de message, voir send_order) ou les caracteres
            # de controle (retour a la ligne, etc.).
            if not re.match(r'^[0-9]+(\|[^|~"\\\x00-\x1f]*)*$', order):
                self._send_json({"error": "ordre invalide"}, 400)
                return
            if SEC and not self._need(order_perm(order)):
                return
            if SEC:
                ip = self.client_address[0]
                if _is_disarm_order(order):
                    # desarmement : confirmation explicite obligatoire, mot de passe en plus si l'option est activee
                    if data.get("confirm") is not True:
                        SEC.audit(ip, "DESARMEMENT_REFUSE", "confirmation absente")
                        self._send_json({"error": "Confirmation requise pour desarmer (champ confirm).", "need": "confirm"}, 409)
                        return
                    if SEC.disarm_needs_password() and not self._apikey:
                        if not str(data.get("password", "")):
                            self._send_json({"error": "Mot de passe requis pour desarmer.", "need": "password"}, 403)
                            return
                        if not self._check_pw(ip, data.get("password", "")):
                            return
                    SEC.audit(self._who(), "DESARMEMENT", "confirme")
                else:
                    SEC.audit(self._who(), "ORDRE", "621|***" if order.startswith("621|") else mask(order))
            server = WEB_SERVER_REF
            if not server:
                self._send_json({"error": "serveur non demarre"}, 503)
                return
            ok, msg = server.order(order)
            self._send_json({"ok": ok, "message": msg})
        elif parsed.path == "/api/photo":
            ident = str(data.get("id", "")).strip()
            server = WEB_SERVER_REF
            if not ident.isdigit():
                self._send_json({"error": "numero de camera invalide"}, 400)
                return
            if not server:
                self._send_json({"error": "serveur non demarre"}, 503)
                return
            ok, msg = server.photo(ident)
            self._send_json({"ok": ok, "message": msg})
        elif parsed.path in ("/api/camera/detection", "/api/camera/ring"):
            ident = str(data.get("id", "")).strip()
            server = WEB_SERVER_REF
            try:
                mode = int(data.get("mode"))
                if parsed.path.endswith("detection"):
                    val = bool(data.get("on"))
                else:
                    val = int(data.get("value"))
            except (TypeError, ValueError):
                self._send_json({"error": "parametres invalides"}, 400)
                return
            if not ident.isdigit() or mode not in (1, 2, 4):
                self._send_json({"error": "camera ou mode invalide"}, 400)
                return
            if not server:
                self._send_json({"error": "serveur non demarre"}, 503)
                return
            kind = "detection" if parsed.path.endswith("detection") else "ring"
            ok, msg = server.camera_setting(kind, ident, mode, val,
                                            str(data.get("mac", "")).strip() or None,
                                            str(data.get("token", "")).strip() or None)
            self._send_json({"ok": ok, "message": msg})
        elif parsed.path == "/api/photo/retention":
            try:
                days = int(data.get("days"))
            except (TypeError, ValueError):
                days = -1
            if days not in PHOTO_RETENTION_DAYS or not WEB_LEARNER_REF:
                self._send_json({"error": "duree invalide"}, 400)
                return
            L = WEB_LEARNER_REF
            with L.lock:
                L.kb["photo_retention_days"] = days
                L.dirty = True
            L.save()
            self._send_json({"ok": True, "days": days, "purged": purge_photos(days)})
        elif parsed.path == "/api/video/delete":
            name = delete_latest_video()
            self._send_json({"ok": name is not None, "deleted": name})
        elif parsed.path == "/api/live/stop":
            server = WEB_SERVER_REF
            ok, msg = server.live_stop() if server else (True, "")
            self._send_json({"ok": ok, "message": msg})
        elif parsed.path == "/api/photo/delete":
            names = data.get("names") or []
            done = 0
            for n in names if isinstance(names, list) else []:
                pp = photo_path(str(n))
                if pp:
                    try:
                        os.remove(pp)
                        done += 1
                    except OSError:
                        pass
            self._send_json({"ok": True, "deleted": done})
        elif parsed.path == "/api/camera/privacy":
            ident = str(data.get("id", "")).strip()
            server = WEB_SERVER_REF
            if not ident.isdigit():
                self._send_json({"error": "numero de camera invalide"}, 400)
                return
            if not server:
                self._send_json({"error": "serveur non demarre"}, 503)
                return
            ok, msg = server.camera_privacy(ident, bool(data.get("on")),
                                            str(data.get("mac", "")).strip() or None,
                                            str(data.get("token", "")).strip() or None)
            self._send_json({"ok": ok, "message": msg})
        elif parsed.path in ("/api/live", "/api/camera/sensitivity"):
            ident = str(data.get("id", "")).strip()
            server = WEB_SERVER_REF
            if not ident.isdigit():
                self._send_json({"error": "numero de camera invalide"}, 400)
                return
            if not server:
                self._send_json({"error": "serveur non demarre"}, 503)
                return
            mac = str(data.get("mac", "")).strip() or None
            if parsed.path == "/api/live":
                ok, msg = server.live(ident, mac)
            else:
                try:
                    percent = float(data.get("percent"))
                except (TypeError, ValueError):
                    self._send_json({"error": "pourcentage invalide"}, 400)
                    return
                ok, msg = server.sensitivity(ident, max(0.0, min(100.0, percent)), mac,
                                             str(data.get("token", "")).strip() or None)
            self._send_json({"ok": ok, "message": msg})
        elif parsed.path.startswith("/api/cloud/"):
            learner = WEB_LEARNER_REF
            server = WEB_SERVER_REF
            if not learner:
                self._send_json({"error": "apprentissage desactive (--no-learn)"}, 503)
                return
            act = parsed.path[len("/api/cloud/"):]
            try:
                if act == "reload":
                    self._send_json(cloud_import(learner, explicit=BACKUP_DIR_ARG))
                elif act == "upload":
                    ok, msg = web_cloud_upload(str(data.get("name", "")), str(data.get("content", "")))
                    if ok and data.get("last"):
                        cloud_import(learner, only_dir=os.path.join(WEB_DATA_DIR, "myfox_backup"))
                    self._send_json({"ok": ok, "message": msg})
                elif act == "link":
                    ok, msg = learner.cloud_link(str(data.get("kind", "")), data.get("panel"), data.get("cloud"),
                                                 rename=bool(data.get("rename", True)))
                    self._send_json({"ok": ok, "message": msg})
                elif act == "unlink":
                    self._send_json({"ok": learner.cloud_unlink(str(data.get("kind", "")), data.get("panel"))})
                elif act == "capture":
                    if data.get("cancel"):
                        learner.cancel_capture()
                        self._send_json({"ok": True})
                    elif not server or server.mode != "relais":
                        self._send_json({"ok": False, "message": "Passez en mode relais : c'est le vrai site Myfox qui "
                                                                   "envoie la table du scénario à la centrale."})
                    else:
                        ok, msg = learner.start_capture(data.get("cloud"))
                        self._send_json({"ok": ok, "message": msg})
                elif act == "siteurl":
                    url = str(data.get("url", "")).strip()
                    if not re.match(r"^https?://[A-Za-z0-9.\-]+(:\d+)?$", url.rstrip("/")):
                        self._send_json({"ok": False, "message": "adresse invalide (ex : https://evology.myfox.me)"})
                    else:
                        learner.cloud_site_url(url)
                        self._send_json({"ok": True})
                else:
                    self._send_json({"error": "action inconnue"}, 404)
            except (TypeError, ValueError):
                self._send_json({"ok": False, "message": "parametres invalides"}, 400)
        elif parsed.path == "/api/camera/install":
            srv = WEB_SERVER_REF
            sess = srv.session if srv else None
            if not srv or srv.mode != "autonome":
                self._send_json({"ok": False, "message": "Passez en mode autonome : c'est le script qui envoie l'ordre d'installation."})
            elif not sess or not sess.alive:
                self._send_json({"ok": False, "message": "La centrale n'est pas connectee."})
            elif sess.cam_install and not sess.cam_install.get("done") and time.time() - sess.cam_install["t0"] < 180:
                self._send_json({"ok": False, "message": "Une installation est deja en cours."})
            else:
                try:
                    sess.send_camera_install(data.get("devidx", 150), str(data.get("mac", "")), str(data.get("login", "")),
                                             str(data.get("password", "")), str(data.get("name", "")),
                                             str(data.get("ntp", "pool.ntp.org")), str(data.get("ftp", "")),
                                             bool(data.get("replace")))
                    self._send_json({"ok": True})
                except ValueError as e:
                    self._send_json({"ok": False, "message": str(e)})
                except (OSError, socket.error):
                    self._send_json({"ok": False, "message": "Envoi impossible : connexion perdue avec la centrale."})
        elif parsed.path == "/api/notify":
            if NOTIFIER is None:
                self._send_json({"ok": False, "message": "notifications indisponibles"})
            else:
                NOTIFIER.update(data.get("config"))
                self._send_json({"ok": True})
        elif parsed.path == "/api/notify/test":
            if NOTIFIER is None:
                self._send_json({"ok": False, "message": "notifications indisponibles"})
            else:
                ok, msg = NOTIFIER.test(str(data.get("channel", "")))
                self._send_json({"ok": ok, "message": msg})
        elif parsed.path == "/api/update":
            if UPDATER is None:
                self._send_json({"ok": False, "message": "indisponible"})
            else:
                UPDATER.set_enabled(bool(data.get("enabled")))
                self._send_json({"ok": True})
        elif parsed.path == "/api/update/check":
            ok, msg = UPDATER.check() if UPDATER else (False, "indisponible")
            self._send_json({"ok": ok, "message": msg if not ok else "ok", "info": UPDATER.info() if UPDATER else {}})
        elif parsed.path == "/api/identity":
            sn1 = str(data.get("sn1", "")).strip()
            sn2 = str(data.get("sn2", "")).strip().lower()
            model = str(data.get("model", "")).strip()      # "" = automatique d'apres la MAC
            if sn1 and not re.match(r"^\d{8}$", sn1):
                self._send_json({"ok": False, "message": "SN1 : 8 chiffres exactement (étiquette sous la centrale)."})
            elif sn2 and not re.match(r"^[0-9a-f]{12}$", sn2):
                self._send_json({"ok": False, "message": "SN2 : 12 caractères hexadécimaux (ex : 0004a3…)."})
            elif model not in CENTRALE_MODELS:
                self._send_json({"ok": False, "message": "modèle inconnu"})
            elif not WEB_LEARNER_REF:
                self._send_json({"ok": False, "message": "apprentissage désactivé (--no-learn) : réglage impossible."})
            else:
                with WEB_LEARNER_REF.lock:
                    _det = (WEB_LEARNER_REF.kb.get("settings") or {}).get("detected")
                    _dmac = (WEB_LEARNER_REF.kb.get("settings") or {}).get("detected_mac")
                    WEB_LEARNER_REF.kb["settings"] = {"sn1": sn1, "sn2": sn2, "model": model}
                    if _det:
                        WEB_LEARNER_REF.kb["settings"]["detected"] = _det
                    if _dmac:
                        WEB_LEARNER_REF.kb["settings"]["detected_mac"] = _dmac
                    WEB_LEARNER_REF.dirty = True
                WEB_LEARNER_REF.save()
                sess = WEB_SERVER_REF.session if WEB_SERVER_REF else None
                self._send_json({"ok": True, "source_id": make_source_id(WEB_LEARNER_REF.kb["settings"], sess.mac if sess else None)})
        elif parsed.path == "/api/name":
            ident = str(data.get("id", "")).strip()
            name = str(data.get("name", "")).strip()
            if not re.match(r"^s?\d+$", ident):
                self._send_json({"error": "identifiant invalide"}, 400)
                return
            if WEB_DATA_DIR:
                set_name(WEB_DATA_DIR, ident, name)
            self._send_json({"ok": True})
        elif parsed.path == "/api/type":
            ident = str(data.get("id", "")).strip()
            label = str(data.get("type", "")).strip()[:40]
            if not ident.isdigit():
                self._send_json({"error": "identifiant invalide"}, 400)
                return
            if WEB_LEARNER_REF:
                WEB_LEARNER_REF.set_ctype(ident, label)
            self._send_json({"ok": True})
        elif parsed.path == "/api/sensor/tempsettings":
            # "Capteur de temperature integre" (Oui/Non) + "Decalage de la temperature relevee" (C) :
            # confirme le 25 octobre comme des reglages geres UNIQUEMENT cote cloud Myfox (aucun ordre
            # envoye a la centrale meme en les changeant sur le vrai site). Ce script les applique donc
            # lui-meme, localement, sur l'affichage de la temperature du capteur concerne (section
            # "Capteurs & temperatures") -- rien n'est envoye sur le relais pour ce reglage.
            learner = WEB_LEARNER_REF
            if not learner:
                self._send_json({"error": "serveur non demarre"}, 503)
                return
            try:
                n = int(data.get("id"))
            except (TypeError, ValueError):
                self._send_json({"error": "identifiant invalide"}, 400)
                return
            try:
                offset = float(data.get("offset", 0))
            except (TypeError, ValueError):
                self._send_json({"error": "decalage invalide"}, 400)
                return
            enabled = bool(data.get("enabled", True))
            kb = learner.kb
            kb.setdefault("sensor_temp_settings", {})[str(n)] = {"enabled": enabled, "offset": offset}
            learner.dirty = True
            learner.save()
            self._send_json({"ok": True})
        elif parsed.path == "/api/relay":
            server = WEB_SERVER_REF
            if not server:
                self._send_json({"error": "serveur non demarre"}, 503)
                return
            enable = bool(data.get("enable"))
            server.set_relay(enable)
            self._send_json({"ok": True, "mode": server.mode})
        elif parsed.path == "/api/scenario":
            server = WEB_SERVER_REF
            learner = WEB_LEARNER_REF
            if not server or not learner:
                self._send_json({"error": "serveur non demarre"}, 503)
                return
            try:
                mode = str(data.get("mode", "demande"))
                if mode not in MODES:
                    self._send_json({"error": "mode de declenchement invalide"}, 400)
                    return
                days = {}
                for k, v in (data.get("days") or {}).items():
                    if not str(k).isdigit():
                        continue
                    items = []
                    if mode in ("evenement", "presence"):
                        for rng in (v or [])[:2]:
                            if len(rng) != 2:
                                continue
                            (h1, m1), (h2, m2) = rng
                            h1, m1, h2, m2 = int(h1), int(m1), int(h2), int(m2)
                            if 0 <= h1 < 24 and 0 <= m1 < 60 and 0 <= h2 < 24 and 0 <= m2 < 60:
                                items.append(((h1, m1), (h2, m2)))
                    else:
                        for pair in (v or [])[:4]:
                            h, m = int(pair[0]), int(pair[1])
                            if 0 <= h < 24 and 0 <= m < 60:
                                items.append((h, m))
                    if items:
                        days[int(k)] = items
                event = None
                ev = data.get("event") or {}
                if mode == "evenement":
                    kind = str(ev.get("kind", ""))
                    if kind == "securite":
                        event = ("securite", int(ev.get("val", 0)) & 7)
                    elif kind == "risque":
                        event = ("risque", int(ev.get("val", 0)) & 0xffff)
                    elif kind == "capteur":
                        event = ("capteur", int(ev.get("val", 0)))
                    elif kind == "capteur_temp":
                        event = ("capteur_temp", (int(ev.get("devidx", 0)), int(round(float(ev.get("seuil", 0)) * 8)),
                                                  1 if ev.get("sens") == "hausse" else 0))
                    else:
                        self._send_json({"error": "type d'evenement invalide"}, 400)
                        return
                condition = data.get("condition")
                condition = int(condition) if condition not in (None, "", "aucune") else None
                devices = {}
                for k, v in (data.get("devices") or {}).items():
                    if str(k).isdigit() and int(v) in (0, 2):
                        devices[int(k)] = int(v)
                security = data.get("security")
                security = int(security) if security not in (None, "", "aucune") else None
                ring = bool(data.get("ring"))
                delay = data.get("delay")
                delay = int(delay) if delay not in (None, "") else None
                run = data.get("run")
                run = int(run) if run not in (None, "", "aucun") else None
                inverse_delay = data.get("inverse_delay")
                inverse_delay = int(inverse_delay) if inverse_delay not in (None, "") else None
                t1, t2 = build_scenario_table(mode=mode, days=days or None, event=event, condition=condition,
                                              devices=devices or None, security=security, ring=ring,
                                              delay=delay, run=run, inverse_delay=inverse_delay)
            except (ValueError, TypeError, KeyError) as e:
                self._send_json({"error": "parametres invalides : %s" % e}, 400)
                return
            kb = learner.kb
            ident = data.get("id")
            if ident not in (None, "", "new"):
                try:
                    n = int(ident)
                except ValueError:
                    self._send_json({"error": "identifiant de scenario invalide"}, 400)
                    return
            else:
                # un scenario supprime (ordre 2101) reste dans scenario_tables (seul scenario_deleted est marque),
                # donc on l'exclut ici de la meme facon que web_build_state() l'exclut de la liste affichee --
                # sinon son numero reste considere "pris" pour toujours et ne se re-utilise jamais.
                deleted = kb.get("scenario_deleted", {})
                tables = kb.get("scenario_tables", {})
                used = set()
                for k in tables:
                    if not str(k).isdigit():
                        continue
                    if str(k) in deleted and tables.get(str(k)) and deleted[str(k)] >= tables[str(k)][-1]["time"]:
                        continue
                    used.add(int(k))
                used |= set(int(k) for k in kb.get("scenarios", {}) if str(k).isdigit())
                n = 0
                while n in used:
                    n += 1
            ok, msg = server.order("2100|%d|%s|%s" % (n, t1, t2))
            if ok:
                name = str(data.get("name", "")).strip()
                if name and WEB_DATA_DIR:
                    set_name(WEB_DATA_DIR, "s%d" % n, name)
            self._send_json({"ok": ok, "message": msg, "id": n})
        elif parsed.path == "/api/scenario/toggle":
            # "Desactiver" un scenario : l'etat active/desactive n'existe PAS dans la table du protocole
            # (section 10, octet 422 : "le nom du scenario et son etat active/desactive ne sont PAS dans
            # la table ; le cloud les garde") et la centrale EXECUTE ELLE-MEME ses scenarios programmes/sur
            # evenement (section 1), sans intervention du serveur -- il n'existe donc aucun ordre "coupe le
            # scenario N" a envoyer. Le seul levier reel est de reecrire la table (ordre 2100) en remplacant
            # le declenchement par "a la demande" (mode 0, sans horaire ni evenement) : la centrale ne peut
            # alors plus le lancer seule, mais l'action (equipements, securite...) reste intacte et le
            # scenario repond toujours a un lancement manuel (ordre 2102, bouton ON). On garde l'ancienne
            # definition (declenchement d'origine) en base pour pouvoir la restaurer a la reactivation.
            server = WEB_SERVER_REF
            learner = WEB_LEARNER_REF
            if not server or not learner:
                self._send_json({"error": "serveur non demarre"}, 503)
                return
            try:
                n = int(data.get("id"))
            except (TypeError, ValueError):
                self._send_json({"error": "identifiant de scenario invalide"}, 400)
                return
            enable = bool(data.get("enable"))
            kb = learner.kb
            tabs = kb.get("scenario_tables", {}).get(str(n))
            if not tabs:
                self._send_json({"error": "scenario inconnu (jamais vu passer sur le relais)"}, 404)
                return
            saved_specs = kb.setdefault("scenario_disabled_spec", {})
            if enable:
                saved = saved_specs.get(str(n))
                if not saved:
                    self._send_json({"ok": False, "message": "aucun declenchement d'origine enregistre pour ce "
                                     "scenario (il n'a pas ete desactive depuis ce script) : rien a restaurer."})
                    return
                t1, t2 = build_scenario_table(**scenario_spec_to_kwargs(saved))
            else:
                saved_specs[str(n)] = parse_scenario_spec(tabs[-1]["t1"])
                kwargs = scenario_spec_to_kwargs(saved_specs[str(n)])
                kwargs["mode"], kwargs["days"], kwargs["event"] = "demande", None, None
                t1, t2 = build_scenario_table(**kwargs)
            ok, msg = server.order("2100|%d|%s|%s" % (n, t1, t2))
            if ok:
                if enable:
                    saved_specs.pop(str(n), None)
                    kb.setdefault("scenario_disabled", {}).pop(str(n), None)
                else:
                    kb.setdefault("scenario_disabled", {})[str(n)] = iso(time.time())
            self._send_json({"ok": ok, "message": msg})
        else:
            self._send_json({"error": "not found"}, 404)


class ThreadingHTTPServer(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads = True
    allow_reuse_address = True


def start_web(port, server_ref, learner_ref, data_dir, log):
    global WEB_SERVER_REF, WEB_LEARNER_REF, WEB_DATA_DIR
    WEB_SERVER_REF, WEB_LEARNER_REF, WEB_DATA_DIR = server_ref, learner_ref, data_dir
    try:
        httpd = ThreadingHTTPServer(("0.0.0.0", port), DashboardHandler)
    except OSError as e:
        log.line("TABLEAU DE BORD WEB IMPOSSIBLE : port %d indisponible (%s)." % (port, e))
        return
    log.line("TABLEAU DE BORD WEB - http://<ip de ce PC>:%d" % port)
    threading.Thread(target=_photo_purge_loop, daemon=True).start()
    threading.Thread(target=httpd.serve_forever, daemon=True).start()


# --------------------------------------------------------------------------
# SERVEUR DNS INTEGRE (--dns) -- alternative a Pi-hole/dnsmasq (section 4/18) pour rediriger
# automatiquement core.steadyfox.com (et hc2.steadyfox.com) vers ce script, SANS toucher a la
# configuration DNS du reseau a la main.
# --------------------------------------------------------------------------
# Principe : un petit serveur DNS (UDP) qui repond LUI-MEME, avec l'IP de cette machine, pour les noms
# que la centrale resout (voir --reference section 4) ; pour TOUT le reste (le reste d'internet, les
# autres appareils du reseau si ce script est aussi utilise comme serveur DNS pour eux), il se contente
# de relayer la requete telle quelle vers un vrai serveur DNS (--dns-upstream) et de renvoyer sa reponse.
# Pour que la centrale (ou le reseau) utilisent ce serveur, il faut soit :
#   - configurer MANUELLEMENT la centrale/le routeur pour utiliser l'IP de cette machine comme DNS
#     (si la centrale ou le routeur le permettent) ;
#   - ou (plus simple en pratique) faire distribuer cette IP comme DNS par le serveur DHCP du routeur --
#     dans ce cas TOUT le reseau passe par ce relais, d'ou l'importance du relais transparent ci-dessus.
# SECURITE : comme le reste de ce script (voir l'avertissement en tete de fichier), ce serveur DNS n'a
# aucune authentification -- ne jamais l'exposer sur internet, le garder sur le reseau local.
# Necessite generalement les droits root sous Linux : le port DNS standard (53) est un port privilegie
# (< 1024). --dns-port permet de changer de port si ce script ne peut/ne doit pas tourner en root (il
# faudra alors rediriger le port 53 vers --dns-port par une regle de pare-feu, ou utiliser setcap
# CAP_NET_BIND_SERVICE sur l'executable python3).
DNS_DEFAULT_DOMAINS = ("core.steadyfox.com", "hc2.steadyfox.com")


def detect_local_ip():
    """Adresse IP de cette machine sur le reseau local -- par le truc habituel (socket UDP "connectee"
    a une adresse externe SANS rien envoyer : le systeme choisit juste l'interface de sortie et son IP).
    Repli sur gethostbyname(hostname), puis 127.0.0.1 si tout echoue (machine sans reseau)."""
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            s.connect(("8.8.8.8", 80))
            return s.getsockname()[0]
        finally:
            s.close()
    except OSError:
        pass
    try:
        return socket.gethostbyname(socket.gethostname())
    except OSError:
        return "127.0.0.1"


def detect_default_dns_upstream():
    """Premier "nameserver" de /etc/resolv.conf (le vrai DNS du reseau, en general la box/le routeur),
    en ignorant une eventuelle boucle sur cette machine elle-meme ; repli sur 1.1.1.1 (Cloudflare) si
    /etc/resolv.conf est absent/illisible (Windows, conteneur minimal...) ou ne contient rien d'utilisable."""
    try:
        with open("/etc/resolv.conf", encoding="utf-8") as f:
            for raw in f:
                parts = raw.split()
                if len(parts) >= 2 and parts[0] == "nameserver" and parts[1] not in ("127.0.0.1", "::1"):
                    return parts[1]
    except OSError:
        pass
    return "1.1.1.1"


def dns_parse_question(data):
    """Decode juste la PREMIERE question d'une requete DNS : nom demande, QTYPE, QCLASS, et la position
    ou elle se termine dans le paquet. Renvoie None pour tout ce qu'on ne sait pas decoder (QDCOUNT=0,
    paquet tronque, nom compresse dans la question -- rarissime pour une question, mais on prefere
    s'abstenir que mal interpreter) : l'appelant transfere alors simplement la requete telle quelle."""
    if len(data) < 12:
        return None
    qdcount = int.from_bytes(data[4:6], "big")
    if qdcount < 1:
        return None
    labels = []
    offset = 12
    while True:
        if offset >= len(data):
            return None
        length = data[offset]
        if length == 0:
            offset += 1
            break
        if length & 0xC0:          # pointeur de compression -- pas attendu dans une question, on s'abstient
            return None
        offset += 1
        label = data[offset:offset + length]
        if len(label) != length:
            return None
        labels.append(label.decode("ascii", "replace"))
        offset += length
    if offset + 4 > len(data):
        return None
    qtype = int.from_bytes(data[offset:offset + 2], "big")
    qclass = int.from_bytes(data[offset + 2:offset + 4], "big")
    return ".".join(labels), qtype, qclass, offset + 4


def dns_build_answer(query, ip, ttl=60):
    """Construit une reponse DNS complete (A/IN) a partir de la requete brute "query" et de l'IP a
    renvoyer -- reprend l'ID et la question telle quelle (y compris sa casse d'origine), ajoute UNE
    reponse (nom par pointeur de compression vers la question, 0xC0 0x0C -- toujours juste apres
    l'entete de 12 octets). Renvoie None si la requete n'est pas une question A/IN exploitable (laisse
    alors l'appelant transferer vers le vrai DNS, par exemple pour une requete AAAA)."""
    parsed = dns_parse_question(query)
    if not parsed:
        return None
    _qname, qtype, qclass, qend = parsed
    if qtype != 1 or qclass != 1:          # seulement A/IN ; le reste (AAAA...) part vers --dns-upstream
        return None
    try:
        ip_bytes = socket.inet_aton(ip)
    except OSError:
        return None
    req_flags = int.from_bytes(query[2:4], "big")
    rd = req_flags & 0x0100                # on recopie le bit RD de la requete, comme un vrai serveur
    flags = 0x8000 | 0x0400 | 0x0080 | rd  # QR=1 (reponse), AA=1 (autoritaire), RA=1, RD recopie
    header = (query[0:2] + flags.to_bytes(2, "big") + (1).to_bytes(2, "big")
              + (1).to_bytes(2, "big") + (0).to_bytes(2, "big") + (0).to_bytes(2, "big"))
    question = query[12:qend]
    answer = (b"\xc0\x0c" + (1).to_bytes(2, "big") + (1).to_bytes(2, "big")
              + ttl.to_bytes(4, "big") + (4).to_bytes(2, "big") + ip_bytes)
    return header + question + answer


def dns_forward(query, upstream_host, upstream_port, timeout=3.0):
    """Relaie une requete telle quelle vers un vrai serveur DNS et renvoie sa reponse brute (ou None si
    injoignable/pas de reponse a temps) -- utilise pour tout ce que ce serveur ne capte pas lui-meme."""
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            s.settimeout(timeout)
            s.sendto(query, (upstream_host, upstream_port))
            data, _ = s.recvfrom(4096)
            return data
        finally:
            s.close()
    except OSError:
        return None


def _dns_build_query(name, qtype=1):
    """Construit une requete DNS minimale (une question, QTYPE/QCLASS donnes) pour 'name'."""
    qid = random.randint(0, 65535)
    header = (qid.to_bytes(2, "big") + (0x0100).to_bytes(2, "big") + (1).to_bytes(2, "big")
              + (0).to_bytes(2, "big") + (0).to_bytes(2, "big") + (0).to_bytes(2, "big"))
    qname = b"".join(bytes([len(p)]) + p.encode("ascii", "replace") for p in name.split(".") if p) + b"\x00"
    question = qname + qtype.to_bytes(2, "big") + (1).to_bytes(2, "big")
    return header + question


def resolve_upstream_host(host, log=None):
    """Resout 'host' en passant directement par un resolveur DNS PUBLIC (1.1.1.1 puis 8.8.8.8), SANS
    passer par le resolveur du systeme -- indispensable en mode relais (ModeController._run_relay) :
    l'hote vise (par defaut core.steadyfox.com) est normalement redirige par le reseau local (Pi-hole/
    dnsmasq/routeur, ou le serveur DNS integre --dns, voir plus haut) vers CE boitier, pour que la
    centrale lui parle. Un gethostbyname()/socket.create_connection() classique heriterait de cette
    MEME redirection et renverrait donc l'adresse du boitier lui-meme : le mode relais se connecterait
    alors a lui-meme au lieu du vrai serveur Myfox, d'ou le symptome observe le 5 novembre (la centrale
    se montre bien connectee ici, mais disparait du site/application Myfox officiels, puisqu'elle ne
    les atteint jamais). On interroge donc un resolveur public, dont la reponse n'est pas affectee par
    la redirection locale. Renvoie 'host' tel quel si c'est deja une IP, ou si aucun resolveur public
    n'a repondu (le code appelant tente alors la connexion avec le nom tel quel, comme avant ce correctif)."""
    try:
        ipaddress.ip_address(host)
        return host
    except ValueError:
        pass
    query = _dns_build_query(host)
    for resolver in ("1.1.1.1", "8.8.8.8"):
        data = dns_forward(query, resolver, 53, timeout=3.0)
        if not data or len(data) < 12:
            continue
        ancount = int.from_bytes(data[6:8], "big")
        if ancount < 1:
            continue
        pos = len(query)      # la reponse recopie l'entete + la question telles quelles (meme taille)
        ip = None
        for _ in range(ancount):
            if pos + 2 > len(data):
                break
            if data[pos] & 0xC0 == 0xC0:          # nom compresse (pointeur) : 2 octets
                pos += 2
            else:                                  # nom en clair : labels jusqu'a l'octet 0
                while pos < len(data) and data[pos] != 0:
                    pos += 1 + data[pos]
                pos += 1
            if pos + 10 > len(data):
                break
            rtype = int.from_bytes(data[pos:pos + 2], "big")
            rdlength = int.from_bytes(data[pos + 8:pos + 10], "big")
            pos += 10
            if rtype == 1 and rdlength == 4 and pos + 4 <= len(data):
                ip = ".".join(str(b) for b in data[pos:pos + 4])
                break
            pos += rdlength
        if ip:
            if log:
                log.line("MODE RELAIS : %s resolu en %s via le resolveur public %s." % (host, ip, resolver))
            return ip
    if log:
        log.line("MODE RELAIS : impossible de resoudre %s via un resolveur public -- utilisation du nom "
                  "tel quel (risque d'auto-relais si ce nom est redirige localement)." % host)
    return host


def start_dns_server(args, log):
    if not args.dns:
        return None
    domains = set(d.lower().rstrip(".") for d in (list(DNS_DEFAULT_DOMAINS) + (args.dns_domain or [])))
    answer_ip = args.dns_ip or detect_local_ip()
    upstream_host, _, upstream_port_s = args.dns_upstream.partition(":")
    upstream_port = int(upstream_port_s) if upstream_port_s else 53
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        sock.bind(("0.0.0.0", args.dns_port))
    except OSError as e:
        extra = " (droits root necessaires pour un port < 1024 ?)" if args.dns_port < 1024 else ""
        log.line("SERVEUR DNS IMPOSSIBLE : port %d indisponible (%s)%s." % (args.dns_port, e, extra))
        return None

    def handle(data, addr):
        parsed = dns_parse_question(data)
        reply = None
        matched = None
        if parsed:
            qname = parsed[0].lower().rstrip(".")
            if qname in domains:
                matched = qname
                reply = dns_build_answer(data, answer_ip)
        if reply is None:
            reply = dns_forward(data, upstream_host, upstream_port)
        if reply is not None:
            try:
                sock.sendto(reply, addr)
            except OSError:
                pass
        if matched:
            log.line("DNS : %s -> %s (demande par %s:%d)" % (matched, answer_ip, addr[0], addr[1]), show=False)

    def loop():
        while True:
            try:
                data, addr = sock.recvfrom(512)
            except OSError:
                break
            threading.Thread(target=handle, args=(data, addr), daemon=True).start()

    threading.Thread(target=loop, daemon=True).start()
    log.line("SERVEUR DNS ACTIF sur le port %d - redirige %s vers %s, transfere le reste vers %s:%d"
             % (args.dns_port, ", ".join(sorted(domains)), answer_ip, upstream_host, upstream_port))
    return sock

