# Console (mode autonome)
# --------------------------------------------------------------------------
# Aide de la console du mode autonome (documentation, section 3).
AIDE = """
Commandes :
  partiel | total | desarme      armement de l'alarme (niveaux 2 / 4 / 1)
  on N | off N                   allume / eteint l'appareil numero N (ex : on 160)
  scenario N                     lance le scenario numero N de la centrale
  etat                           etat de la connexion, dernier niveau d'alarme, appareils vus
  equipements | inventaire       inventaire des equipements connus
  nom N "nom"                    nomme un appareil (N) ou un scenario (sN) sans redemarrer
  declarer N [devmod]            declare manuellement l'appareil n.N (deja appaire avant ce script,
                                  jamais vu passer sur le relais) pour qu'il apparaisse sur le
                                  tableau de bord ; devmod optionnel (ex : declarer 23 49)
  devmod N M                     complete le devmod M d'un appareil n.N DEJA connu (historique
                                  conserve) ; utilise ca, pas 'declarer', si 'equipements' montre
                                  deja n.N sans devmod (ex : devmod 8 49)
  raw XXX                        envoie un ordre brut deja vu dans les captures (ex : raw 226|10)
  calibrer N                     lance la calibration de l'IntelliTAG numero N (ordre 226|N) -- voir attention ci-dessous
  photo N                        demande une photo a la camera n.N (ordre 619) ; enregistree dans myfox_data/photos
  live N                         demande le flux video de la camera n.N (ordre 620) ; flux brut dans myfox_data/videos
  sensibilite N POURCENT         regle la sensibilite de la camera n.N (ordre 613 ; POURCENT de 0 a 100)
  detection N MODE 0|1           detection de mouvement de la camera n.N dans un mode (MODE 1 desarme, 2 partiel, 4 total)
  sonore N MODE VALEUR           signalisation sonore (ordre 205 ; VALEUR 0 aucune, 2 bips, 9/8/7 bips 12/30/60 s puis sirene, 10 sirene)
  aide                           cette aide
  quit                           quitte

ATTENTION calibrer : manipuler le tag leve une alarme "Auto-protection" (type 8, libelle du vrai site, compte
comme intrusion pour l'editeur de scenario) ; lors de l'observation le scenario d'intrusion s'est execute,
meme en etat desarme. Verifie ce que fait ton scenario d'intrusion avant de calibrer.
La calibration dure environ 2 min 30 s ; elle se termine sans message de fin (la centrale cesse simplement
d'envoyer des rapports apres cpt ~17). Ne lance pas d'autre ordre pendant ce temps.
"""


def console(server, data_dir):
    print(AIDE)
    while True:
        try:
            line = input("> ").strip()
        except EOFError:                       # lance sans terminal (service, nohup) : on reste en attente
            try:
                while True:
                    time.sleep(3600)
            except KeyboardInterrupt:
                return
        except KeyboardInterrupt:
            print()
            return
        if not line:
            continue
        cmd, _, arg = line.partition(" ")
        cmd = cmd.lower()
        arg = arg.strip()
        if cmd in ("quit", "exit", "q"):
            return
        elif cmd in ("aide", "help", "?"):
            print(AIDE)
        elif cmd in ORDRES:
            ok, msg = server.order(ORDRES[cmd][0])
            if not ok:
                print(msg)
        elif cmd in ("on", "off") and arg.isdigit():
            ok, msg = server.order("400|%s|%d" % (arg, 2 if cmd == "on" else 0))
            if not ok:
                print(msg)
        elif cmd == "scenario" and arg.isdigit():
            ok, msg = server.order("2102|%s" % arg)
            if not ok:
                print(msg)
        elif cmd == "photo" and arg.isdigit():
            ok, msg = server.photo(arg)
            if ok:
                print("Photo demandee a la camera n.%s (ordre 619). La centrale repond en quelques secondes ; "
                      "l'image sera enregistree dans %s" % (arg, PHOTO_DIR))
            else:
                print(msg)
        elif cmd == "live" and arg.isdigit():
            ok, msg = server.live(arg)
            if ok:
                print("Flux video demande a la camera n.%s (ordre 620). Le flux brut sera enregistre dans %s" % (arg, VIDEO_DIR))
            else:
                print(msg)
        elif cmd in ("sensibilite", "sensibilité") and re.match(r"^\d+\s+\d+(\.\d+)?$", arg):
            cam, pct = arg.split()
            ok, msg = server.sensitivity(cam, float(pct))
            print(msg)
        elif cmd == "detection" and re.match(r"^\d+ [124] [01]$", arg):
            cam, mode, on = arg.split()
            print(server.camera_setting("detection", cam, int(mode), on == "1")[1])
        elif cmd == "sonore" and re.match(r"^\d+ [124] \d+$", arg):
            cam, mode, val = arg.split()
            print(server.camera_setting("ring", cam, int(mode), int(val))[1])
        elif cmd == "raw" and re.match(r"^[0-9a-f|]+$", arg):
            ok, msg = server.order(arg)
            if not ok:
                print(msg)
        elif cmd in ("calibrer", "recalibrer", "calibration") and arg.isdigit():
            ok, msg = server.order("226|%s" % arg)
            if ok:
                print("Calibration demandee pour l'IntelliTAG n.%s (226|%s). Suis les rapports calib / offx / cpt ; "
                      "une alarme \"Auto-protection\" (type 8) va etre levee pendant la manipulation." % (arg, arg))
            else:
                print(msg)
        elif cmd in ("equipements", "inventaire"):
            if server.learner:
                print("\n".join(inventory_lines(server.learner.kb, server.session.devices if server.session and server.session.alive else ())))
            else:
                print("Apprentissage desactive (--no-learn) : pas d'inventaire.")
        elif cmd == "nom":
            num, _, nom = arg.partition(" ")
            if re.match(r"^s?\d+$", num) and nom.strip():
                set_name(data_dir, num, nom.strip().strip('"'))
            else:
                print('Usage : nom 17 Salon   (ou : nom s3 "Armement partiel")')
        elif cmd == "declarer" and arg:
            parts = arg.split()
            num = parts[0]
            devmod = parts[1] if len(parts) > 1 else None
            if not num.isdigit():
                print('Usage : declarer 23 [49]   (declare l\'appareil n.23, devmod 49 optionnel)')
            elif not server.learner:
                print("Apprentissage desactive (--no-learn) : impossible de declarer un appareil.")
            elif server.learner.declare_device(num, devmod):
                print("OK : appareil n.%s declare manuellement%s. Il apparait maintenant dans "
                      "l'inventaire et sur le tableau de bord web (tu peux le renommer avec 'nom')."
                      % (num, (" (devmod %s)" % devmod) if devmod else ""))
            else:
                print("n.%s est deja connu (voir 'equipements') : rien fait, pour ne pas ecraser son historique. "
                      "Utilise 'devmod %s %s' pour juste completer son devmod." % (num, num, devmod or "49"))
        elif cmd == "devmod":
            parts = arg.split()
            if len(parts) == 2 and parts[0].isdigit():
                num, devmod = parts
                if not server.learner:
                    print("Apprentissage desactive (--no-learn) : impossible de completer le devmod.")
                elif server.learner.set_devmod(num, devmod):
                    print("OK : devmod %s assigne a l'appareil n.%s (historique conserve)." % (devmod, num))
                else:
                    print("n.%s est totalement inconnu : utilise 'declarer %s %s' a la place." % (num, num, devmod))
            else:
                print('Usage : devmod 8 49   (complete le devmod 49 de l\'appareil deja connu n.8)')
        elif cmd == "etat":
            s = server.session
            if not s or not s.alive:
                print("Centrale NON connectee.")
            else:
                print("Centrale connectee depuis %d s (%s). Niveau d'alarme rapporte : %s. Appareils vus : %s"
                      % (time.time() - s.since, s.addr[0], s.seclev, sorted(s.devices)))
        else:
            print("Commande inconnue. Tape 'aide'.")


# ----------------------------------------------------------------------------------------------------------
# INTEGRATION DAEMON JEEDOM NATIF (push + canal de commandes), en remplacement de l'emulation REST ci-dessus
# ----------------------------------------------------------------------------------------------------------
# Suite a la demande explicite de l'utilisateur le 30 octobre ("vrai daemon Jeedom natif (push+socket)") :
# ce script peut desormais, en plus (ou a la place, cote plugin) de l'emulation api.myfox.me/v2, parler le
# protocole standard des daemons Python Jeedom via le module "jeedom.py" fourni par l'utilisateur, range
# depuis le 31 octobre en sous-package resources/jeedom/jeedom.py (import "from jeedom.jeedom import ...",
# comme le squelette officiel des daemons Jeedom -- juste les imports serial/pyudev rendus optionnels dans
# ce fichier, non utilises ici) :
#   - CANAL DE COMMANDES (plugin -> ce script) : un petit serveur TCP local (127.0.0.1, port --socketport)
#     recoit une ligne JSON {"request": "<chemin>"} -- EXACTEMENT les memes chemins
#     que l'emulation REST (/site/.../security/set/armed, /site/.../device/<id>/socket/on, /site/.../
#     scenario/<id>/play...), traites par la MEME fonction pure cloud2_dispatch_path() -- seul le transport
#     change (socket au lieu de HTTP), pas le "protocole". Cote PHP, AlarmemyfoxCmd::execute() (action)
#     envoie cette ligne au lieu de faire un curl vers MYFOXURL.
#   - PUSH (ce script -> plugin) : toutes les --jeedom-cycle secondes, construit l'etat (web_build_state(),
#     cloud2_security()...), compare au precedent, et pour chaque valeur qui a change appelle
#     jeedom_com.add_changes("<eqlogic_id>::cmd::<logicalId>", valeur) -- jeedom.py poste alors un JSON vers
#     --callback (avec ?apikey=, valeur de --apikey) ; cote PHP, jeeAlarmemyfox.php (nouveau fichier) recoit
#     ce POST et appelle $cmd->event($valeur) sur la bonne commande. Remplace le cron "pull" + GET REST :
#     plus besoin d'attendre jusqu'a une minute, la valeur part des qu'elle change.
# Cmd pousses (logicalId, voir core/class/Alarmemyfox.class.php::postUpdate pour leur creation) : "etat"
# (statusLabel brut "armed"/"partial"/"disarmed" -- jeeAlarmemyfox.php applique convertLang), "etat1"
# (seclev brut "1"/"2"/"4" -- jeeAlarmemyfox.php applique converbinary), "temperature<deviceId>" (un par
# capteur de temperature), "Event_Last" (dernier evenement, horodate comme le faisait l'ancien execute()).
# PAS pousses, faute de source locale equivalente (deja documente dans cloud2_devices_of_type) :
# luminosite<deviceId>, other<deviceId>, heater<deviceId>, et les Event_<categorie> specifiques (alarm/
# security/scenario/account/access/config/diagnosis/homeAuto) -- notre historique local (RECENT_EVENTS)
# n'est pas categorise par type comme l'etait l'API cloud ; seul Event_Last (toutes categories confondues)
# est fiable a pousser.
# Si jeedom.py ou une dependance (requests) manque, l'integration est simplement DESACTIVEE (message dans
# le journal) -- le reste du script (TCP 8888, tableau de bord, emulation REST) continue de fonctionner.
# Import/arguments alignes sur le squelette standard des daemons Jeedom (generateur officiel) : le module
# vit dans un sous-package "jeedom" a cote de ce script (resources/jeedom/jeedom.py), importe comme
# "jeedom.jeedom" -- pas "jeedom" tout court -- et les options CLI reprennent les noms courts habituels
# (--apikey/--callback/--socketport/--loglevel/--pid), demande explicitement le 31 octobre.
def start_jeedom_daemon(args, controller, log):
    if not (args.apikey and args.callback and args.jeedom_eqlogic_id):
        return None
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    try:
        from jeedom.jeedom import jeedom_com, jeedom_socket, JEEDOM_SOCKET_MESSAGE, jeedom_utils
    except ImportError as e:
        log.line("INTEGRATION JEEDOM DESACTIVEE (jeedom/jeedom.py ou une dependance manquante -- pip3 install requests -- : %s)" % e)
        return None
    # jeedom_utils.set_log_level(args.loglevel) : deja fait plus tot dans main(), inconditionnellement
    # (voir son commentaire) -- pas besoin de le refaire ici.
    com = jeedom_com(apikey=args.apikey, url=args.callback, cycle=args.jeedom_cycle)
    sock = jeedom_socket(address="127.0.0.1", port=args.socketport)
    try:
        sock.open()
    except OSError as e:
        log.line("INTEGRATION JEEDOM : port de commandes %d indisponible (%s)." % (args.socketport, e))
        return None
    eqid = args.jeedom_eqlogic_id

    def consumer():
        while True:
            line = JEEDOM_SOCKET_MESSAGE.get()
            try:
                msg = json.loads(line.decode("utf-8", "replace").strip())
                path = msg.get("request") or msg.get("path") or ""
                if path:
                    cloud2_dispatch_path(path)
            except (ValueError, AttributeError) as e:
                log.line("Commande Jeedom invalide (%r) : %s" % (line, e))
    threading.Thread(target=consumer, daemon=True).start()

    def pusher():
        last = {}
        while True:
            try:
                state = web_build_state()
                changes = {}
                code = state.get("seclev")
                if code:
                    label = cloud2_security(state).get("statusLabel", "")
                    if label and last.get("etat") != label:
                        changes["etat"] = label
                        last["etat"] = label
                    code_s = str(code)
                    if last.get("etat1") != code_s:
                        changes["etat1"] = code_s
                        last["etat1"] = code_s
                names = {}
                for s in state.get("sensors", []):
                    if s.get("temp") is None:
                        continue
                    k = "temperature%d" % s["id"]
                    if last.get(k) != s["temp"]:
                        changes[k] = s["temp"]
                        last[k] = s["temp"]
                        # Nom lisible du capteur (demande le 4 novembre : avoir "Fenetre cellier" plutot que
                        # "temperature0" dans Jeedom) -- pousse A PART (branche "name", pas "cmd") et
                        # UNIQUEMENT utilise par jeeAlarmemyfox.php pour NOMMER la commande si elle vient
                        # d'etre creee (logicalId, lui, reste "temperature<id>" : stable, jamais ce nom qui
                        # peut changer si l'appareil est renomme cote tableau de bord).
                        if s.get("name"):
                            names[k] = s["name"]
                # Filtre demande le 4 novembre : seuls niveau d'alarme / alarme declenchee (intrusion...) /
                # batterie faible / connexion-deconnexion de la centrale sont pousses -- voir
                # _is_notable_event() (plus haut) pour la liste exacte. On regarde les 20 derniers
                # evenements (le plus recent en tete, cloud2_history()) pour trouver le premier qui matche,
                # au lieu du tout dernier evenement quel qu'il soit (qui etait souvent un simple rapport de
                # temperature de routine).
                notable = next((h for h in cloud2_history(20) if _is_notable_event(h["label"])), None)
                if notable and last.get("Event_Last") != notable["label"]:
                    changes["Event_Last"] = _event_last_label(notable["label"])
                    last["Event_Last"] = notable["label"]
                for k, v in changes.items():
                    com.add_changes("%s::cmd::%s" % (eqid, k), v)
                for k, v in names.items():
                    com.add_changes("%s::name::%s" % (eqid, k), v)
            except Exception as e:
                log.line("Erreur boucle push Jeedom : %s" % e)
            time.sleep(max(1.0, args.jeedom_cycle))
    threading.Thread(target=pusher, daemon=True).start()
    log.line("INTEGRATION JEEDOM ACTIVE - commandes sur 127.0.0.1:%d, push vers %s toutes les %gs"
             % (args.socketport, args.callback, args.jeedom_cycle))
    return com

def main():
    ap = argparse.ArgumentParser(description="Serveur local de test pour centrale Myfox")
    ap.add_argument("--port", type=int, default=8888, help="port d'ecoute (8888 par defaut)")
    # --guard-port : option OPT-IN (desactivee par defaut, aucun impact si absente). Problème constate le
    # 1er novembre : la centrale garde sa connexion TCP ouverte en permanence ; redemarrer ce script (mise
    # a jour, bug...) casse forcement cette connexion, et EN PRATIQUE la centrale ne s'est PAS reconnectee
    # seule meme apres plusieurs minutes d'attente (contrairement a la note de la section 4 -- fais
    # confiance a cette observation reelle, pas a la doc). Avec --guard-port N : ce script (le "backend")
    # n'ecoute plus directement sur --port (donc jamais sur l'IP de la centrale), mais UNIQUEMENT sur
    # 127.0.0.1:N. Le port externe reellement vu par la centrale doit alors etre tenu par le process
    # SEPARE ET PERMANENT myfox_tcp_guard.py (voir ce fichier, a cote de celui-ci), qui lui ne redemarre
    # jamais en meme temps que ce backend : la connexion TCP de la centrale vers lui ne casse donc plus.
    # Demarrage typique :  python3 myfox_tcp_guard.py --listen-port 8888 --backend-port N --log F
    # (le lancer en permanence, separement du cycle demarrage/arret de ce script -- PAS via
    # deamon_start()/deamon_stop() cote Jeedom, qui ne gerent aujourd'hui que ce backend).
    ap.add_argument("--guard-port", type=int, default=None,
                     help="(opt-in) backend en ecoute UNIQUEMENT sur 127.0.0.1:N au lieu de --port ; "
                          "voir myfox_tcp_guard.py pour exposer le vrai port a la centrale sans jamais "
                          "couper sa connexion TCP lors d'un redemarrage de ce script")
    ap.add_argument("--relay", action="store_true", help="mode relais/espion vers le vrai serveur")
    ap.add_argument("--upstream", default="core.steadyfox.com:8888", help="vrai serveur (mode relais)")
    ap.add_argument("--log", default=os.path.join(app_dir(), "myfox_server.log"))
    ap.add_argument("--verbose", action="store_true", help="affiche aussi les rapports de routine")
    here = app_dir()
    # Par defaut, "data" a la racine du plugin Jeedom (un niveau au-dessus de resources/, ou vit ce
    # script) -- convention standard des plugins Jeedom (dossier non ecrase par les mises a jour).
    # Cree automatiquement s'il n'existe pas encore (voir juste apres ap.parse_args() plus bas).
    plugin_root = os.path.dirname(here)
    ap.add_argument("--data-dir", default=os.path.join(plugin_root, "data"),
                    help="dossier de l'apprentissage (data/ a la racine du plugin par defaut ; cree s'il n'existe pas)")
    ap.add_argument("--no-learn", action="store_true", help="desactive l'apprentissage automatique")
    ap.add_argument("--skip-acks", action="store_true",
                    help="ne journalise pas les accuses de reception ordinaires du serveur (journal plus petit)")
    ap.add_argument("--journal-mb", type=int, default=20,
                    help="taille maximale d'un fichier de journal avant rotation, en Mo (20 par defaut)")
    ap.add_argument("--web-port", type=int, default=8081, help="port du tableau de bord web (8080 par defaut)")
    ap.add_argument("--no-web", action="store_true", help="desactive le tableau de bord web")
    # Serveur DNS integre (voir start_dns_server()) : alternative a Pi-hole/dnsmasq pour rediriger
    # automatiquement core.steadyfox.com/hc2.steadyfox.com vers ce script (section 4/18 de --reference).
    ap.add_argument("--dns", action="store_true",
                    help="active un serveur DNS integre qui redirige automatiquement core.steadyfox.com "
                         "et hc2.steadyfox.com vers ce script (evite de configurer Pi-hole/dnsmasq a la "
                         "main) ; transfere toute autre requete vers --dns-upstream, sans effet sur le "
                         "reste du reseau")
    ap.add_argument("--dns-port", type=int, default=53,
                    help="port d'ecoute du serveur DNS integre (53, le port standard, par defaut -- "
                         "necessite generalement les droits root sous Linux pour un port < 1024)")
    ap.add_argument("--dns-ip", default=None, metavar="ADRESSE",
                    help="adresse IP renvoyee pour core.steadyfox.com/hc2.steadyfox.com (auto-detectee "
                         "par defaut : adresse IP locale de cette machine)")
    ap.add_argument("--dns-upstream", default=detect_default_dns_upstream(), metavar="HOTE[:PORT]",
                    help="vrai serveur DNS vers lequel transferer tout ce que ce script ne capte pas "
                         "lui-meme (par defaut : le DNS de ce reseau, lu dans /etc/resolv.conf, sinon "
                         "1.1.1.1)")
    ap.add_argument("--dns-domain", action="append", metavar="DOMAINE",
                    help="domaine additionnel a rediriger vers ce script, en plus de core.steadyfox.com "
                         "et hc2.steadyfox.com (repetable)")
    ap.add_argument("--allow-public", action="store_true",
                    help="accepte aussi les connexions venant d'adresses non locales (deconseille : tableau de bord et port de la centrale)")
    ap.add_argument("--allow-host", action="append", default=[], metavar="NOM",
                    help="nom d'hote accepte pour le tableau de bord (ex : maison.example.org) ; repeter l'option si besoin")
    ap.add_argument("--reset-password", action="store_true",
                    help="supprime tous les comptes et cles d'integration du tableau de bord (en cas d'oubli), puis quitte")
    ap.add_argument("--backup-dir", default=None, metavar="DOSSIER",
                    help="dossier de la sauvegarde du cloud Myfox (noms des scenarios et equipements ; defaut : <data-dir>/myfox_backup)")
    ap.add_argument("--backup-check", action="store_true", help="montre ce que le script trouve dans la sauvegarde du cloud, puis quitte")
    ap.add_argument("--cloud-dump", action="store_true",
                    help="recupere sur l'API Myfox les noms des scenarios et des equipements (identifiants demandes au clavier, rien d'ecrit sur disque)")
    ap.add_argument("--dump-all", action="store_true", help="avec --cloud-dump : sauvegarde aussi historiques, utilisateurs, plannings (donnees personnelles)")
    ap.add_argument("--reference", action="store_true",
                    help="affiche la documentation complete du protocole et le dictionnaire des ordres, puis quitte")
    ap.add_argument("--catalog", action="store_true",
                    help="affiche le catalogue des modeles d'appareils du site Myfox (reference seulement -- ne pas utiliser pour appairer), puis quitte")
    ap.add_argument("--source-id", default=None, metavar="SN1SN2",
                    help="identifiant d'emetteur (20 caracteres = SN1 + SN2 de l'etiquette de la centrale) ; sinon reglage du tableau de bord")
    ap.add_argument("--report", action="store_true", help="affiche le resume de ce qui a ete appris, puis quitte")
    ap.add_argument("--selftest", action="store_true",
                    help="verifie que l'encodeur reproduit a l'octet pres les tables reelles de ton installation, puis quitte")
    ap.add_argument("--build-scenario", nargs=2, metavar=("NUMERO", "JSON"),
                    help='affiche l\'ordre 2100 d\'un scenario, ex : --build-scenario 15 \'{"mode":"demande","devices":{"158":2}}\'')
    ap.add_argument("--rebuild", action="store_true", help="reconstruit la base a partir du journal, puis quitte")
    ap.add_argument("--name", nargs=2, metavar=("NUMERO", "NOM"),
                    help='donne un nom a un appareil ou a un scenario, ex : --name 154 "Volet PF"  ou  --name s3 "Prise 1 ON"')
    ap.add_argument("--names", action="store_true", help="liste les noms connus et les numeros encore sans nom")
    ap.add_argument("--timeline", action="store_true", help="affiche le journal en clair (qui a fait quoi), puis quitte")
    ap.add_argument("--last", type=int, default=40, help="avec --timeline : nombre d'evenements affiches (40)")
    ap.add_argument("--shift-hours", type=float, default=0.0,
                    help="avec --timeline : decale les heures affichees (ex : 1 si la box a 1 h de retard sur toi)")
    ap.add_argument("--all", action="store_true", help="avec --timeline : affiche aussi les rapports de routine")
    ap.add_argument("--inventory", action="store_true", help="affiche l'inventaire des equipements connus, puis quitte")
    ap.add_argument("--cloud-key", action="store_true",
                    help="affiche (en la generant si besoin) la cle API de l'emulation cloud locale "
                         "(plugin Jeedom AlarmeMyfox, etc. -- voir section 9/18), puis quitte")
    ap.add_argument("--pid", metavar="FICHIER",
                    help="ecrit le PID de ce processus dans ce fichier au demarrage, le supprime a l'arret "
                         "propre (Ctrl+C, SIGTERM) -- permet a un programme externe (ex. le daemon d'un "
                         "plugin domotique, voir section 9/18) de savoir si ce script tourne")
    # Noms courts alignes sur le squelette standard des daemons Jeedom (generateur officiel), demande le
    # 31 octobre : --apikey/--callback/--socketport/--loglevel (au lieu de --jeedom-apikey/etc. utilises
    # avant cette date). --jeedom-eqlogic-id et --jeedom-cycle restent prefixes : propres a ce script
    # (le squelette standard n'a qu'un seul "eqLogic" implicite ; nous poussons plusieurs cles par
    # equipement, voir eqid dans start_jeedom_daemon ci-dessus).
    ap.add_argument("--apikey", metavar="CLE",
                    help="active l'integration daemon Jeedom natif (voir section 18 bis) : cle API du "
                         "plugin (jeedom::getApiKey('Alarmemyfox') cote PHP)")
    ap.add_argument("--callback", metavar="URL",
                    help="URL du callback PHP qui recoit les changements pousses (ex. http://127.0.0.1/"
                         "plugins/Alarmemyfox/core/php/jeeAlarmemyfox.php)")
    ap.add_argument("--jeedom-eqlogic-id", metavar="ID",
                    help="identifiant de l'equipement (eqLogic) Jeedom dont les commandes seront mises a "
                         "jour (prefixe des cles poussees, cote PHP : eqLogic_id::cmd::logicalId)")
    ap.add_argument("--socketport", type=int, default=55009,
                    help="port local (127.0.0.1) sur lequel ce script ecoute les commandes envoyees par "
                         "le plugin PHP (armer/desarmer, prise, scenario... -- 55009 par defaut)")
    ap.add_argument("--jeedom-cycle", type=float, default=3.0,
                    help="frequence (secondes) de l'envoi des changements vers Jeedom (3 s par defaut)")
    ap.add_argument("--loglevel", default="error", choices=["debug", "info", "notice", "warning", "error", "critical", "none"],
                    help="niveau de log du module jeedom/jeedom.py (error par defaut)")
    args = ap.parse_args()
    global PHOTO_DIR, VIDEO_DIR, BACKUP_DIR_ARG, SOURCE_ID_OVERRIDE
    BACKUP_DIR_ARG = args.backup_dir
    # Verifie/cree --data-dir (data/ a la racine du plugin par defaut) AVANT toute utilisation plus bas
    # (apprentissage, photos, videos, comptes de securite...) -- demande explicite du 31 octobre.
    try:
        os.makedirs(args.data_dir, exist_ok=True)
    except OSError as e:
        print("ATTENTION : impossible de creer --data-dir %s (%s)" % (args.data_dir, e), file=sys.stderr)
    if args.source_id:
        if not re.match(r"^[0-9a-fA-F]{20}$", args.source_id):
            ap.error("--source-id : 20 caracteres hexadecimaux (SN1 sur 8 chiffres + SN2 sur 12)")
        SOURCE_ID_OVERRIDE = args.source_id.lower()
    PHOTO_DIR = os.path.join(args.data_dir, "photos")
    VIDEO_DIR = os.path.join(args.data_dir, "videos")
    if args.reset_password:
        _s = Security(args.data_dir)
        _had = _s.has_password()
        _s.remove_all()
        _s.audit("console", "PROTECTION_RETIREE", "--reset-password")
        print("Comptes et cles d'integration supprimes : le tableau de bord est ouvert (creez un compte dans l'onglet Securite)."
              if _had else "Aucun compte n'etait defini.")
        return

    if args.reference:
        print_reference()
        return

    if args.catalog:
        print_catalog()
        return

    if args.selftest:
        sys.exit(selftest_tables())
    if args.backup_check:
        print_backup_check(args.data_dir, args.backup_dir)
        return
    if args.cloud_dump:
        sys.exit(cloud_dump(args.backup_dir or os.path.join(args.data_dir, "myfox_backup"), args.dump_all))
    if args.build_scenario:
        import json as _json
        spec = _json.loads(args.build_scenario[1])
        if "event" in spec:
            spec["event"] = tuple(spec["event"])
        if "days" in spec:
            spec["days"] = {int(k): [tuple(tuple(x) if isinstance(x, list) and x and isinstance(x[0], list) else x for x in item) if isinstance(item, list) else item for item in v] for k, v in spec["days"].items()}
            spec["days"] = {k: [((tuple(i[0]), tuple(i[1])) if isinstance(i[0], (list, tuple)) else tuple(i)) for i in v] for k, v in spec["days"].items()}
        if "devices" in spec:
            spec["devices"] = {int(k): int(v) for k, v in spec["devices"].items()}
        t1, t2 = build_scenario_table(**spec)
        print("2100|%d|%s|%s" % (int(args.build_scenario[0]), t1, t2))
        return
    if args.name:
        if not re.match(r"^s?\d+$", args.name[0]):
            ap.error("--name : le premier argument doit etre un numero d'appareil (ex : 154) ou un scenario (ex : s3)")
        set_name(args.data_dir, args.name[0], args.name[1])
        return
    load_names(args.data_dir)
    if args.names:
        list_names(args.data_dir)
        return
    if args.timeline:
        timeline(args.data_dir, args.last, args.shift_hours, args.all)
        return
    if args.rebuild:
        rebuild(args.data_dir)
        return
    if args.report:
        print_report(os.path.join(args.data_dir, "myfox_knowledge.json"))
        return
    if args.inventory:
        print("\n".join(inventory_lines(load_kb(os.path.join(args.data_dir, "myfox_knowledge.json")))))
        return
    if args.cloud_key:
        _l = Learner(args.data_dir, announce=lambda *a: None)
        print("Cle API de l'emulation cloud locale (Client ID = Client Secret a saisir dans le plugin) :")
        print("  " + cloud_api_key(_l))
        return
    # arret propre sur "kill" / "systemctl stop" : la base de connaissances est sauvegardee avant de quitter
    signal.signal(signal.SIGTERM, lambda signum, frame: sys.exit(0))
    global SEC, NOTIFIER, UPDATER
    if os.name == "posix":
        os.umask(0o077)         # fichiers crees par le script (base, journaux, photos, mot de passe) : lisibles par vous seul
    # Configure le module "logging" au niveau Jeedom (--loglevel) INDEPENDAMMENT de l'integration
    # push/socket (start_jeedom_daemon() plus bas, qui ne s'active que si apikey/callback/eqlogic-id sont
    # TOUS fournis) : meme sans cette integration, PHP redirige toujours stdout+stderr vers le log du
    # plugin (voir Log.line() ci-dessus) -- on veut donc toujours ce formatage/filtrage, des que le script
    # tourne sous Jeedom. Si jeedom/jeedom.py (ou une dependance, ex. "requests") manque, l'echec est
    # desormais journalise explicitement ci-dessous plutot que passe sous silence (voir "log" cree juste
    # au-dessus pour pouvoir le faire).
    global JEEDOM_LOGGING_ACTIVE
    log = Log(args.log)
    try:
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        from jeedom.jeedom import jeedom_utils
        jeedom_utils.set_log_level(args.loglevel)
        JEEDOM_LOGGING_ACTIVE = True
    except ImportError as e:
        # AVANT CE CORRECTIF : "except ImportError: pass" -- aucune trace nulle part si jeedom/jeedom.py
        # (ou une de ses dependances, typiquement le paquet "requests") manque : le script tournait quand
        # meme, mais avec le format de log "maison" (HH:MM:SS) au lieu du format Jeedom ([date][NIVEAU]),
        # sans aucune explication visible dans le log du plugin -- cause exacte du symptome "je n'ai pas
        # le systeme de log de jeedom" signale le 1er novembre. Desormais explicite, meme ligne que
        # start_jeedom_daemon() plus bas pour le meme type d'echec.
        log.line("FORMAT DE LOG JEEDOM INDISPONIBLE (jeedom/jeedom.py ou une dependance manquante -- "
                  "verifier notamment 'pip install requests' dans le venv du plugin -- : %s). "
                  "Le script continue avec son propre format de log (HH:MM:SS)." % e)
    SEC = Security(args.data_dir, log, allow_public=args.allow_public, extra_hosts=args.allow_host)
    learner = None if args.no_learn else Learner(args.data_dir, announce=log.line,
                                                 skip_acks=args.skip_acks, journal_mb=args.journal_mb)
    NOTIFIER = Notifier(args.data_dir, log)
    UPDATER = Updater(args.data_dir, log)
    if UPDATER.st["enabled"]:
        UPDATER.start()
    if learner:
        learner.event_hook = notify_hook
    # ModeController demarre dans le mode demande en ligne de commande (--relay ou non), mais peut
    # ensuite etre bascule a chaud depuis le tableau de bord web (bouton "mode relais"), sans redemarrer.
    if learner:
        r = cloud_import(learner, args.backup_dir)
        if r.get("found") and r.get("ok"):
            log.line("Sauvegarde du cloud Myfox : %d scenario(s), %d equipement(s) lus dans %s" % (r["scenarios"], r["devices"], r["dir"]))
        elif not learner.kb.get("cloud"):
            log.line("Pas de sauvegarde du cloud Myfox (noms des scenarios et equipements) : voir --cloud-dump")
    guard_bind_host = "0.0.0.0"
    guard_listen_port = args.port
    if args.guard_port:
        guard_bind_host = "127.0.0.1"
        guard_listen_port = args.guard_port
        log.line("MODE GARDE TCP (--guard-port) : ce backend n'est joignable QUE sur 127.0.0.1:%d. "
                  "Demarrez separement 'python3 myfox_tcp_guard.py --listen-port %d --backend-port %d' "
                  "pour exposer le port a la centrale -- sinon elle ne pourra jamais se connecter."
                  % (guard_listen_port, args.port, guard_listen_port))
    controller = ModeController(guard_listen_port, args.upstream, log, learner, args.verbose, bind_host=guard_bind_host)
    controller.set_relay(args.relay)
    if not args.no_web:
        start_web(args.web_port, controller, learner, args.data_dir, log)
    start_dns_server(args, log)
    start_jeedom_daemon(args, controller, log)
    if args.pid:
        try:
            os.makedirs(os.path.dirname(os.path.abspath(args.pid)) or ".", exist_ok=True)
            with open(args.pid, "w", encoding="utf-8") as f:
                f.write(str(os.getpid()))

            def _remove_pid_file():
                try:
                    os.remove(args.pid)
                except OSError:
                    pass
            atexit.register(_remove_pid_file)
            log.line("PID %d ecrit dans %s" % (os.getpid(), args.pid))
        except OSError as e:
            log.line("IMPOSSIBLE D'ECRIRE --pid %s : %s" % (args.pid, e))
    time.sleep(0.3)
    try:
        console(controller, args.data_dir)
    except KeyboardInterrupt:
        print()
    print("Arret.")


if __name__ == "__main__":
    main()
